  function filterProducts(){const list=module==='custom'?customProducts:wholeProducts,q=($('#productSearch')?.value||'').toLowerCase(),cat=$('#productCategory')?.value||'全部分类',filtered=list.filter(p=>(cat==='全部分类'||p.category===cat)&&(!q||[p.name,p.category,p.unit].join(' ').toLowerCase().includes(q)));if($('#productRows'))$('#productRows').innerHTML=`<table><thead><tr><th>项目名称</th><th>分类</th><th>计价单位</th><th>默认计价方式</th><th>演示单价</th><th></th></tr></thead><tbody>${productRows(filtered)}</tbody></table>`}
  document.addEventListener('change',e=>{if(e.target.id==='factoryOcrKind'){factoryOcrKind=e.target.value;factoryOcrText='';renderFactoryOcrReview([factoryOcrBlank(factoryOcrKind)],factoryOcrKind,'');const status=$('#factoryOcrStatus');if(status)status.textContent='单据类型已切换，请上传对应图片或手动录入。'}if(e.target.matches('#factoryOcrForm [name="document"]')){const file=e.target.files?.[0],kind=$('#factoryOcrKind')?.value||'板材单';if(file){factoryOcrFile=file;recognizeFactoryBill(file,kind)}}if(e.target.id==='roleSelect')setRole(e.target.value);if(e.target.id==='stageFilter'&&e.target.value){const rows=sampleCustomers.filter(c=>c.stage===e.target.value);$('#customerRows').innerHTML=customerRows(rows)}if(e.target.id==='productCategory')filterProducts()});
  document.addEventListener('submit',e=>{if(e.target.id!=='frameworkEditForm')return;e.preventDefault();const form=e.target,d=new FormData(form),kind=form.dataset.kind,gi=Number(form.dataset.group),ii=Number(form.dataset.item),name=String(d.get('name')||'').trim(),desc=String(d.get('desc')||'').trim();if(!name)return;if(kind==='group'){if(gi>=0){frameworkGroups[gi].name=name;frameworkGroups[gi].hint=desc}else frameworkGroups.push({name,hint:desc,items:[]})}else{const value={name,desc,glyph:String(d.get('glyph')||'▦').trim()||'▦'};if(ii>=0)frameworkGroups[gi].items[ii]=value;else frameworkGroups[gi].items.push(value)}persistDemo();frameworkEditing=true;render();toast('模块结构已保存在当前浏览器')},true);
  document.addEventListener('submit',async e=>{e.preventDefault();if(e.target.id==='customerForm'){const d=new FormData(e.target),name=String(d.get('name')||'').trim();if(!name)return;const customer={id:`C-${Date.now()}`,name,phone:String(d.get('phone')||'').trim(),community:String(d.get('community')||'未填写项目').trim(),source:d.get('source')||'其他',owner:d.get('owner')||'未分配',type:d.get('type')||'整装',stage:d.get('stage')||'线索',due:d.get('nextAt')||'未安排',nextAt:d.get('nextAt')||'',nextPlan:String(d.get('nextPlan')||'').trim(),tag:'amber'};sampleCustomers.unshift(customer);persistDemo();$('#modalRoot').innerHTML='';if(window.__customerToQuote){window.__customerToQuote=false;cqNew(customer.id)}else{toast('客户档案已建立');render()}}else if(e.target.id==='demoForm'){const file=$('[type=file]',e.target)?.files?.[0];$('#modalRoot').innerHTML='';toast(file?`已选择 ${file.name}（仅演示，未上传）`:'演示记录已提交')}});
