  const renderBase=render;render=function(){if(page==='factory-order-detail'){renderNav();$('#roleSelect').value=role;$('#crumbModule').textContent='工厂订单详情';$('#view').innerHTML=factoryOrderDetailPage();return}if(page==='customer-detail'){renderNav();$('#roleSelect').value=role;$('#crumbModule').textContent='客户详情';$('#view').innerHTML=customerDetailPage();return}if(module==='factory'&&page==='factory-jobs'){renderNav();$('#roleSelect').value=role;$('#view').innerHTML=factoryJobsPage();return}renderBase()};
