  const cqPreviousDraft=quoteDraftFromPage;
  quoteDraftFromPage=function(){const q=cqPreviousDraft();if(module!=='custom'||!$('#cqRoomNav'))return q;const raw=cqRows().map(r=>({name:$('[data-item]',r).value,material:JSON.parse(r.dataset.material||'{}'),included:$('[data-included]',r).value==='included',charge:$('[data-included]',r).value,includedIn:$('[data-included-in]',r).value,expandedArea:Number($('[data-expanded]',r).value||0),purchaseReference:r.dataset.reference!==''?Number(r.dataset.reference):undefined,source:r.dataset.source||'',standalonePrice:Number($('[data-included]',r).value==='extra'?$('[data-price]',r).value:r.dataset.standalonePrice||0),upgradePrice:Number($('[data-included]',r).value==='upgrade'?$('[data-price]',r).value:r.dataset.upgradePrice||0)})).filter(r=>r.name);const rows=q.rows.map((r,i)=>({...r,...raw[i]})),discount=Number($('#cqDiscount').value||0),deliveryFee=Number($('#cqDeliveryFee').value||0),installFee=Number($('#cqInstallFee').value||0);return {...q,id:quoteDraftId||`CQ-${Date.now()}`,rooms:[...cqRooms],activeRoom:cqRoom,rows,customerType:$('#cqCustomerType').value,contact:$('#cqContact').value,phone:$('#cqPhone').value,channel:$('#cqChannel').value,payments:$('#cqPayments').value,channelTerms:$('#cqChannelTerms').value,subtotal:q.amount,discount,deliveryFee,installFee,amount:Math.max(0,q.amount-discount+deliveryFee+installFee),documents:cqState.draft?.documents||[],projectedPrice:Number($('#cqProjectedPrice').value||0),linearPrice:Number($('#cqLinearPrice').value||0),baseMaterial:cqState.draft?.baseMaterial||{},doorMaterial:cqState.draft?.doorMaterial||{},factoryOrderNo:$('#cqOrderNo')?.value||'',measurementDate:$('#cqMeasureDate')?.value||'',deliveryDate:$('#cqDeliveryDate')?.value||'',clientProjectedArea:Number($('#cqProjectedArea')?.value||0),clientDoorArea:Number($('#cqDoorArea')?.value||0),orderNote:$('#cqCustomerNote')?.value||''}};
