    if(name==='cq-apply-rates'){const a=Number($('#cqProjectedPrice').value||0),b=Number($('#cqLinearPrice').value||0);cqRows().filter(r=>['柜体定制','厨房工程'].includes($('[data-category]',r).value)&&!$('[data-price]',r).disabled&&$('[data-included]',r).value!=='upgrade').forEach(r=>{const mode=$('[data-unit]',r).value;if(mode==='投影面积')$('[data-price]',r).value=a;if(mode==='延米')$('[data-price]',r).value=b});recalc();cqCapture();toast('已更新柜体项目单价，增项与补差保留');return}
