  async function foSummaryRecognize(){const f=$('#foSummaryFile')?.files[0],form=$('#foSummaryForm');if(!f){toast('先选择报价单图片');return}if(form.dataset.busy)return;form.dataset.busy='yes';form.querySelector('[type="submit"]').disabled=true;$('#foSummaryStatus').textContent='正在识别，请核对文字…';try{const T=await loadTesseract(),worker=await T.createWorker(['chi_sim','eng']);try{const result=await worker.recognize(f);if($('#foSummaryForm')===form){form.elements.text.value=result.data.text||'';$('#foSummaryStatus').textContent='识别完成，需要手动确认客户及金额'}}finally{await worker.terminate()}}catch(_){if($('#foSummaryForm')===form)$('#foSummaryStatus').textContent='识别未完成，可按原单补录文字或手动建单'}finally{if($('#foSummaryForm')===form){form.dataset.busy='';form.querySelector('[type="submit"]').disabled=false}}}
