    if(form.getAttribute('id')==='foOrderForm'){if(!v.customer.trim()||!v.community.trim()||!positive(v.quote)){toast('填写客户、小区和大于0的接单金额');return}const id=editingFactoryJobId||foId(),old=factoryJobRecords.find(x=>x.id===id),received=old?foReceived(old):0;if(Number(v.depositTarget)>(Number(v.settled)>0?Number(v.settled):Number(v.quote))){toast('约定定金不能超过订单金额');return}if((Number(v.settled)>0?Number(v.settled):Number(v.quote))<received){toast('约定金额不能低于累计已收款，先核对退款');return}if(foCommit(()=>{const target=old||{id,board:0,edging:0,hardware:0,labor:0,outsourcing:0,other:0,status:'已订货',costLines:[],statusHistory:[{status:'已订货',time:localStamp(),note:'建立接单档案'}],createdAt:foDate()};Object.assign(target,v);['quote','settled','depositTarget','cabinetArea','thickness','boardSheets','edgingMeters'].forEach(k=>target[k]=foN(v[k]));target.boardName=[v.boardBrand,v.substrate].filter(Boolean).join(' ');target.boardSpec=[v.thickness?`${v.thickness}mm`:'',v.boardColor,v.boardModel].filter(Boolean).join(' · ');if(!old)factoryJobRecords.unshift(target)})){selectedFactoryJobId=id;module='factory';page='factory-order-detail';foDone('本户接单档案已保存')}return}
    if(form.getAttribute('id')==='foStageForm'){if(!j)return;if(!v.operator.trim()){toast('填写更新人');return}if(foCommit(()=>{j.status=v.status;j.statusHistory||=[];j.statusHistory.push({status:v.status,date:v.date,time:localStamp(),operator:v.operator,note:v.note})}))foDone('工序与今日记录已保存');return}
    if(form.getAttribute('id')==='foCostForm'){if(!j||!positive(v.amount)){toast('成本必须大于0');return}if(foCommit(()=>{const id=foId(),amount=foN(v.amount);foCost(j,v.category,amount,v.note,v.date,id);if(d.has('paid'))foState.cash.push({id:foId(),direction:'out',orderId:j.id,category:v.category,date:v.date,amount,note:v.note,sourceId:id})}))foDone('订单成本已登记，毛利已更新');return}
    if(form.getAttribute('id')==='foPaymentForm'){const job=factoryJobRecords.find(x=>x.id===v.orderId),amount=foN(v.amount);if(!job||!positive(amount)){toast('选择有效订单并填写正金额');return}const current=foReceived(job);if(v.type==='退款'&&amount>foCategoryReceived(job,v.refundAgainst)){toast('退款超过原类别已收金额；请核对退款类别');return}if((v.type==='退款'&&amount>current)||(v.type!=='退款'&&current+amount>factoryRevenue(job))){toast(v.type==='退款'?'退款不可超过已收款':'累计收款超过订单约定金额，请先确认增项调整');return}if(foCommit(()=>foState.payments.push({...v,id:foId(),amount})))foDone('收款记录已保存，应收已更新');return}
