  function uxCustomerDomain(c){return ['whole','custom'].includes(c.businessModule)?c.businessModule:c.type==='全屋定制'?'custom':'whole'}
  const uxCustomerModal=customerModal;
  customerModal=function(c=null){uxCustomerModal(c);const f=$('#customerForm');if(!f)return;const type=f.elements.namedItem('type'),domain=c?uxCustomerDomain(c):module==='custom'?'custom':'whole';type.innerHTML=`<option value="整装" ${domain==='whole'?'selected':''}>整装客户</option><option value="全屋定制" ${domain==='custom'?'selected':''}>定制客户</option>`;if(!c&&['whole','custom'].includes(module)){type.value=module==='whole'?'整装':'全屋定制';type.closest('.form-field').insertAdjacentHTML('beforeend','<small>新客户保存到当前业务，报价从本户档案发起。</small>')}if(c&&c.type==='整装 + 定制')type.closest('.form-field').insertAdjacentHTML('beforeend','<small>旧混合客户请核对业务归属；历史报价原件继续留存。</small>');};
  const uxCustomers=customers;
  customers=function(){const t=document.createElement('template');t.innerHTML=uxCustomers();const count=rxBusinessCustomers().length;for(const el of t.content.querySelectorAll('.toolbar span,.toolbar small'))if(/位客户/.test(el.textContent))el.textContent=`${count} 位客户 · ${module==='custom'?'定制':'整装'}档案`;const filter=t.content.querySelector('#businessFilter');if(filter){filter.innerHTML='<option value="">当前业务客户</option>';filter.hidden=true;}return t.innerHTML};
  const uxDetail=customerDetailPage;
  customerDetailPage=function(){const t=document.createElement('template');t.innerHTML=uxDetail();const c=sampleCustomers.find(x=>x.id===selectedCustomerId);if(c){const domain=uxCustomerDomain(c);t.content.querySelectorAll('[data-action="rx-customer-quote"]').forEach(b=>{if(b.dataset.id!==domain)b.remove()});const head=t.content.querySelector('.page-head .head-actions,.page-head .actions');if(!t.content.querySelector('[data-action="rx-customer-quote"]')&&head)head.insertAdjacentHTML('afterbegin',foBtn(domain==='whole'?'＋ 新建整装报价':'＋ 新建定制报价','rx-customer-quote',domain,true));}return t.innerHTML};

  const uxOwnerHome=ownerHome;
  ownerHome=function(){const t=document.createElement('template');t.innerHTML=uxOwnerHome();const grid=t.content.querySelector('.module-grid');if(grid){grid.classList.add('ux-three-businesses');grid.innerHTML=['custom','whole','factory'].map(kind=>{const factory=kind==='factory',label=factory?'工厂生产':kind==='whole'?'整装业务':'全屋定制',people=sampleCustomers.filter(c=>uxCustomerDomain(c)===kind),quotes=savedQuotes.filter(q=>q.type===(kind==='whole'?'整装':'全屋定制'));return `<button class="module-card ux-business-card" data-route="${kind}/home"><div class="module-card-top"><span class="module-symbol">${factory?'▧':kind==='whole'?'▦':'▤'}</span><span class="module-link">进入业务 →</span></div><h3>${label}</h3><p>${factory?'生产订单、材料领用、工人考勤与工厂收支。':kind==='whole'?'整装客户 → 基装 / 主材报价 → 分期收款 → 工地进程。':'定制客户 → 柜体报价 → 材料确认 → 下单交接。'}</p><div class="module-stats"><span><b>${factory?factoryJobRecords.length:people.length}</b> ${factory?'户订单':'位客户'}</span><span>${factory?'已录直接成本 '+money(factoryJobRecords.reduce((n,j)=>n+directFactoryCost(j),0)):quotes.length+' 份报价'}</span></div></button>`}).join('');}const subtitle=t.content.querySelector('.page-head p');if(subtitle)subtitle.textContent='定制、整装、工厂分别经营；从这里进入各自的客户、报价和生产工作台。';const metric=t.content.querySelector('.cards .metric .metric-label');if(metric)metric.firstChild.textContent='客户档案总数';return t.innerHTML};

  // One billed quantity per cabinet: m² or metres, without a second multiplier.
  const uxQuantity=quoteCalculatedQuantity;
  quoteCalculatedQuantity=function(r){return r.matches('[data-cq-row]')?Math.max(0,Number($('[data-qty]',r)?.value||0)):uxQuantity(r)};
  const uxLine=cqLine;
  cqLine=function(r={}){const t=document.createElement('template');t.innerHTML='<table><tbody>'+uxLine(r)+'</tbody></table>';const row=t.content.querySelector('tr'),cells=[...row.cells],mode=r.mode||'按数量';let qty=r.qty??r.quantity??0;if(r.measureVersion!==2&&['投影面积','延米','展开面积'].includes(mode)){if(mode==='投影面积'&&Number(r.width)>0&&Number(r.height)>0)qty=Number(r.width)*Number(r.height)/1e6;else if(mode==='延米'&&Number(r.width)>0&&!r.directArea)qty=Number(r.width)/1000;else if(!r.directArea&&r.quantity===undefined&&r.qty===1)qty=0;}row.dataset.measureVersion='2';row.dataset.measureSource=r.measureSource||'manual';cells[2].innerHTML=`<select data-unit aria-label="定制计价方式">${['投影面积','延米','按数量','按件','按项','展开面积'].map(m=>`<option ${m===mode?'selected':''}>${m}</option>`).join('')}</select><div class="ux-size-grid"><label>宽 mm<input data-width type="number" min="0" step="any" aria-label="柜体宽度 mm" value="${Number(r.width||0)||''}"></label><label>高 mm<input data-height type="number" min="0" step="any" aria-label="柜体高度 mm" value="${Number(r.height||0)||''}"></label><label>深 mm<input data-depth type="number" min="0" step="any" aria-label="柜体深度 mm" value="${Number(r.depth||0)||''}"></label></div><small class="ux-size-note">宽 × 高自动填㎡；深度仅记录</small><input data-direct-area type="hidden" value="0"><input data-expanded type="hidden" value="${Number(r.expandedArea||0)}"><span data-measure-qty hidden></span>`;const unit=mode==='投影面积'||mode==='展开面积'?'㎡':mode==='延米'?'米':r.unit||'个';cells[3].innerHTML=`<input data-qty type="number" min="0" step="any" value="${Number(qty)||''}" aria-label="计费数量"><small class="quote-unit-hint" data-unit-label="${esc(unit)}">${esc(unit)}</small>`;cells[4].querySelector('[data-price]')?.setAttribute('step','any');return row.outerHTML};
  const uxBuilder=cqBuilder;
  cqBuilder=function(){const t=document.createElement('template');t.innerHTML=uxBuilder();t.content.querySelector('.cq-line-table')?.classList.add('ux-simple-quote');const header=t.content.querySelector('.cq-line-table thead tr');if(header)header.innerHTML=['房间 / 分类','柜子 / 项目','计价 / 尺寸','计费数量','单价','金额','选配 / 备注',''].map(n=>`<th>${n}</th>`).join('');const strip=t.content.querySelector('.rx-quick-cabinets');if(strip)strip.insertAdjacentHTML('afterend','<div class="ux-calculation-note">投影：宽 × 高 = 平方米 × 单价。延米：直接填米数 × 单价。已有面积可直接填“计费数量”，深度不参与投影计价。</div>');return t.innerHTML};
  function uxMeasureRow(row){const mode=$('[data-unit]',row).value,grid=$('.ux-size-grid',row),note=$('.ux-size-note',row),hint=$('.quote-unit-hint',row);if(grid)grid.hidden=mode!=='投影面积';if(note)note.hidden=mode!=='投影面积';if(hint)hint.textContent=mode==='投影面积'||mode==='展开面积'?'㎡':mode==='延米'?'米':hint.dataset.unitLabel||'个';}
  const uxRecalc=recalc;
  recalc=function(){cqRows().forEach(uxMeasureRow);uxRecalc();};
  document.addEventListener('input',e=>{const row=e.target.closest('#quoteLines [data-cq-row]');if(!row)return;if(e.target.matches('[data-width],[data-height]')&&$('[data-unit]',row).value==='投影面积'){const w=Number($('[data-width]',row).value),h=Number($('[data-height]',row).value);row.dataset.measureSource='dimensions';$('[data-qty]',row).value=w>0&&h>0?Number((w*h/1e6).toFixed(6)):'';}else if(e.target.matches('[data-qty]')){row.dataset.measureSource='manual';}},true);
  document.addEventListener('change',e=>{const row=e.target.closest('#quoteLines [data-cq-row]');if(row&&e.target.matches('[data-unit]'))uxMeasureRow(row)},true);
  const uxDraft=quoteDraftFromPage;
  quoteDraftFromPage=function(){const q=uxDraft();if(module==='custom'){q.measureVersion=2;const visibleRows=cqRows().filter(row=>$('[data-item]',row)?.value);q.rows.forEach((r,i)=>{r.measureVersion=2;r.measureSource=visibleRows[i]?.dataset.measureSource||'manual';r.directArea=0;r.quantity=r.qty;r.amount=workshopRound(r.qty*r.price);});}return q;};

  const uxWholeLine=workshopLineRow;
  workshopLineRow=function(x){const t=document.createElement('template');t.innerHTML='<table><tbody>'+uxWholeLine(x)+'</tbody></table>';const row=t.content.querySelector('tr');if(!row)return '';row.classList.add('ux-renovation-row');const fields=['data-room','data-category','data-item','data-unit','data-qty','data-price','data-amount','data-spec'];const nodes=fields.map(k=>row.querySelector('['+k+']'));const hidden=document.createElement('td');hidden.hidden=true;for(const input of row.querySelectorAll('input,select,textarea'))if(!nodes.includes(input)&&!nodes.some(n=>n?.contains(input)))hidden.append(input);for(const td of [...row.cells])td.remove();for(const [i,node] of nodes.entries()){const td=document.createElement('td');if(node){if(i===6){td.setAttribute('data-amount','');td.className='money';td.textContent=node.textContent;}else td.append(node);}row.append(td);}const mode=nodes[3];if(mode){mode.innerHTML=`<option value="按数量">数量计价</option>`;mode.value='按数量';mode.closest('td').hidden=true;}nodes[1]?.setAttribute('aria-label','整装分类');nodes[4]?.setAttribute('aria-label','工程量');const label=document.createElement('input');label.dataset.uxUnit='';label.setAttribute('value',x[11]||'项');label.setAttribute('aria-label','计量单位');const hint=document.createElement('small');hint.className='quote-unit-hint';hint.dataset.unitLabel=label.value;hint.textContent=label.value;const td=document.createElement('td');td.append(label,hint);row.insertBefore(td,row.cells[4]);row.append(hidden);const del=document.createElement('td');del.innerHTML='<button class="icon-btn" data-action="remove-line" aria-label="删除项目">×</button>';row.append(del);return row.outerHTML};
  const uxPlainWholeLine=workshopLineRow;
  workshopLineRow=function(x){const t=document.createElement('template');t.innerHTML='<table><tbody>'+uxPlainWholeLine(x)+'</tbody></table>';const original=t.content.querySelector('[data-category]');if(original){const select=document.createElement('select');select.dataset.category='';select.setAttribute('aria-label','整装分类');original.replaceWith(select);const list=workshopKind==='major'?['地砖 / 墙砖','门窗','卫浴','橱柜','灯具','其他主材']:['水电','防水','木工吊顶','墙面','瓦工','其他基装'],chosen=x[8]||list[0];select.innerHTML=[...new Set([chosen,...list])].map(n=>`<option ${n===chosen?'selected':''}>${esc(n)}</option>`).join('');}return t.content.querySelector('tr').outerHTML;};
  quoteLineRow=workshopLineRow;
  const uxWholeBuilder=workshopBuilder;
  workshopBuilder=function(){const t=document.createElement('template');t.innerHTML=uxWholeBuilder();const table=t.content.querySelector('#quoteLines')?.closest('table');if(table){table.classList.add('ux-whole-table');table.querySelector('thead tr').innerHTML=['房间','分类','项目名称','单位','数量','单价','金额','规格 / 备注',''].map(n=>`<th>${n}</th>`).join('');}const side=t.content.querySelector('.workshop-space-panel');if(side){const details=document.createElement('details');details.className='ux-whole-rooms';details.innerHTML='<summary>房间筛选（可选）</summary>'+side.innerHTML;side.replaceWith(details);}const title=t.content.querySelector('.page-head p');if(title)title.textContent='基装、主材分别报价。可直接手动填项目、单位、数量、单价和备注，也可导入 Excel。';return t.innerHTML};
  document.addEventListener('input',e=>{if(e.target.matches('[data-ux-unit]')){const hint=e.target.parentElement.querySelector('.quote-unit-hint');hint.dataset.unitLabel=hint.textContent=e.target.value;}},true);

  // Old quotes store both a multiplier and the resulting engineering quantity.
  // Restore the billed quantity before presenting the simpler single-price row.
  const uxRestoreWhole=workshopRestoreFields;
  workshopRestoreFields=function(q){if(!q)return;const source=structuredClone(q);source.rows=(source.rows||[]).map(r=>{let qty=Number(r.quantity);if(!Number.isFinite(qty)){qty=Number(r.qty||0);if(r.mode==='投影面积')qty*=Number(r.width||0)*Number(r.height||0)/1e6;else if(r.mode==='延米')qty*=Number(r.width||0)/1000;else if(r.mode==='展开面积')qty*=Math.max(0,2*(Number(r.width||0)+Number(r.height||0))*Number(r.depth||0)/1e6-Number(r.deduct||0));}return {...r,mode:'按数量',qty,price:q.pricingMode==='split'?Number(r.laborPrice||0)+Number(r.materialPrice??r.price??0):r.price};});quotePricingMode='combined';uxRestoreWhole(source);};
  const uxSimpleWholeBuilder=workshopBuilder;
  workshopBuilder=function(){quotePricingMode='combined';const t=document.createElement('template');t.innerHTML=uxSimpleWholeBuilder();t.content.querySelector('#quotePricingMode')?.remove();t.content.querySelector('.workshop-line-table')?.classList.remove('is-split');return t.innerHTML;};
  const uxCleanWholeBuilder=workshopBuilder;
  workshopBuilder=function(){const t=document.createElement('template');t.innerHTML=uxCleanWholeBuilder();for(const el of t.content.querySelectorAll('[data-action="workshop-cost-toggle"],.workshop-internal-summary,[data-action="workshop-delete-selected"]'))el.remove();for(const el of t.content.querySelectorAll('.workshop-category-strip [data-group]'))if(!['基装','主材'].includes(el.dataset.group))el.remove();const title=t.content.querySelector('#workshopRoomTitle');if(title){title.textContent='整户报价清单';title.nextElementSibling.textContent='项目连续填写，房间和分类在每行选择';}const bulk=t.content.querySelector('[data-action="quote-bulk-import"]');if(bulk)bulk.textContent='导入 Excel / 图片';return t.innerHTML;};
  const uxMeasureRecalc=recalc;
  recalc=function(){uxMeasureRecalc();for(const row of cqRows()){const note=$('.ux-size-note',row);if(note)note.textContent=row.dataset.measureSource==='dimensions'?'宽 × 高自动填㎡；深度仅记录':'按手填面积计费；尺寸仅供参考';}};

  const uxExtract=rxExtract;
  rxExtract=async function(file,rotation=0){if(!['localhost','127.0.0.1'].includes(location.hostname))throw Error('手机版当前用于界面预览；扫描识别请在电脑本机版操作。');return uxExtract(file,rotation);};
  const uxAction=action;
  action=function(name,btn){if(['new-customer','new-customer-for-quote'].includes(name)&&module==='all'){openModal('选择新客户所属业务',`<div class="ux-business-choice">${foBtn('新建整装客户','ux-new-customer','whole',true)}${foBtn('新建定制客户','ux-new-customer','custom',true)}</div>`);return;}if(name==='ux-new-customer'){module=btn.dataset.id;page='customers';render();window.__customerToQuote=true;customerModal();return;}if(name==='rx-customer-quote'){const c=sampleCustomers.find(c=>c.id===selectedCustomerId);if(c&&uxCustomerDomain(c)!==btn.dataset.id){toast('请从客户所属业务发起报价');return;}}const result=uxAction(name,btn);if(['fo-outsource','fo-outsource-edit'].includes(name)){$('#foOutsourceForm .fo-fields')?.insertAdjacentHTML('afterbegin','<p class="ux-calculation-note fo-wide">先填项目名称即可保存。供应商、规格、交期可后补；确认成本时再勾选计入订单。</p>');}return result;};

  // A queue retains each supplier invoice and its original attachments. Saving
  // revisions posts category deltas; actual cash entries are never overwritten.
  let uxBills=null,uxBillCategory='';
  const uxCostKeys={'板材':'board','封边':'edging','五金':'hardware','加工人工':'labor','外协':'outsourcing','其他直接成本':'other'};
  function uxBillCategoryOf(line,kind){return kind==='五金单'?'五金':/封边/.test(line.product)?'封边':/包装|打包|运费/.test(line.product)?'其他直接成本':'板材'}
  function uxBillTotals(b){const allocation=feMoneyAlloc(Number(b.discount||0),b.lines.map(l=>Number(l.amount||0))),totals={};b.lines.forEach((l,i)=>{const category=uxBillCategoryOf(l,b.kind);totals[category]=foN((totals[category]||0)+Number(l.amount||0)-allocation[i]);});if(Number(b.otherFee))totals['其他直接成本']=foN((totals['其他直接成本']||0)+Number(b.otherFee));return totals;}
  function uxBlankBill(kind){return {kind,date:foDate(),supplier:'',billNo:'',otherFee:0,discount:0,lines:[],files:[],reviewed:false,rawText:'',readState:'待读取'};}
  function uxQueueState(){const f=$('#foUxBill');if(!f||!uxBills?.queue.length)return;const b=uxBills.queue[uxBills.index];if(!b)return;['supplier','billNo','date','otherFee','discount'].forEach(k=>b[k]=f.elements.namedItem(k)?.value??b[k]);b.lines=$$('#uxBillLines [data-ux-line]').map(row=>Object.fromEntries($$('[data-bill-field]',row).map(el=>[el.dataset.billField,el.value])));b.reviewed=!!f.elements.namedItem('reviewed')?.checked;b.paid=!!f.elements.namedItem('paid')?.checked;}
  function uxBillPreview(b){b.previewFiles??=(b.files||[]).filter(f=>f.type.startsWith('image/')).map(f=>({name:f.name,url:URL.createObjectURL(f)}));return b.previewFiles.map(f=>`<figure class="ux-bill-preview"><figcaption>${esc(f.name)}</figcaption><img src="${f.url}" alt="原单 ${esc(f.name)}"></figure>`).join('');}
  function uxReleaseBillPreviews(){for(const b of uxBills?.queue||[])for(const f of b.previewFiles||[])URL.revokeObjectURL(f.url);}
  function uxBillRow(l={},i=0){const field=(key,label,type='text')=>`<input class="field" data-bill-field="${key}" type="${type}" ${type==='number'?'step="any" min="0"':''} aria-label="${label}" value="${esc(l[key]??'')}">`;return `<tr data-ux-line><td>${field('product','品名')}<details><summary>型号 / 板材属性（可选）</summary><div class="ux-bill-specs">${[['productCode','编码'],['brand','品牌'],['substrate','基材'],['thickness','厚度 mm'],['color','花色'],['spec','规格'],['stockUnit','库存单位'],['packFactor','包装换算']].map(([key,label])=>`<label>${label}${field(key,label)}</label>`).join('')}</div></details></td><td>${field('unit','单位')}</td><td>${field('qty','采购数量','number')}</td><td>${field('unitPrice','采购单价','number')}</td><td>${field('amount','行金额','number')}</td><td>${field('remark','行备注')}<button type="button" class="btn small" data-action="ux-bill-remove" data-id="${i}">移除行</button></td></tr>`;}
  function uxBillRender(){const f=$('#foUxBill');if(!f||!uxBills)return;const b=uxBills.queue[uxBills.index];$('#uxBillQueue').innerHTML=uxBills.queue.map((x,i)=>`<button type="button" class="${i===uxBills.index?'active':''}" data-action="ux-bill-switch" data-id="${i}">${i+1}. ${esc(x.files?.map(f=>f.name).join('、')||x.billNo||'手动登记')}<small>${esc(x.readState||'已登记')} · ${x.lines.length} 项${x.reviewed?' · 已核对':''}${x.saved?' · 已保存':''}</small></button>`).join('');$('#uxBillContent').innerHTML=`<p class="ux-bill-status">${esc(b.error||b.readState||'已读取')}。品名、单位、数量和金额为入账项；品牌、型号可后补。</p><div class="ux-bill-meta">${[['supplier','供应商'],['billNo','单据号（可选）'],['date','日期'],['otherFee','运费 / 其他费用'],['discount','优惠 / 折让']].map(([k,label])=>`<label>${label}<input class="field" name="${k}" type="${k==='date'?'date':['otherFee','discount'].includes(k)?'number':'text'}" ${['otherFee','discount'].includes(k)?'step="any" min="0"':''} value="${esc(b[k]??'')}"></label>`).join('')}</div><div class="ux-bill-lines"><table><thead><tr>${['品名','单位','数量','单价','金额','备注 / 操作'].map(n=>`<th>${n}</th>`).join('')}</tr></thead><tbody id="uxBillLines">${b.lines.map(uxBillRow).join('')}</tbody></table></div><div class="fo-actions">${foBtn('＋ 手动补一行','ux-bill-add')}${foBtn('重新读取当前原单','ux-bill-reread')}</div><div class="ux-bill-summary"><span>本单核对后成本 <small class="ux-bill-total">${b.lines.length} 项 · 不代表已付款</small></span>${b.declaredTotal!=null?`<small>原单合计 ${money(b.declaredTotal)} · 请核对差额</small>`:''}<b id="uxBillTotal">${money(b.lines.reduce((n,l)=>n+Number(l.amount||0),0)+Number(b.otherFee||0)-Number(b.discount||0))}</b></div><label class="ux-bill-status"><input type="checkbox" name="reviewed" ${b.reviewed?'checked':''}> 我已核对本单数量、金额与采购单位</label>${!b.editId?`<p><label class="ux-bill-status"><input type="checkbox" name="paid" ${b.paid?'checked':''}> 本单货款已实际支付，同时登记现金支出</label></p>`:'<p class="ux-bill-status">修改只更正订单成本，保留原单、旧版本和已录付款。</p>'}<details><summary>原单 / 原始识别内容${b.editId?' / 修订历史':''}</summary>${uxBillPreview(b)}<div class="fo-actions">${(b.originalFiles||[]).map(d=>foBtn(esc(d.name),'view-factory-bill-file',d.id)).join('')}</div><pre>${esc(b.rawText||'')}</pre>${b.editId?`<p>${esc(b.revisions?.map((r,i)=>`第${i+1}次修订前：${r.date} · ${r.supplier} · ${money(r.total)}`).join('\n')||'尚无修订')}</p>`:''}</details>`;}
  function uxBillOpen(kind,stock=false,bill=null){uxBills={kind,stock,index:0,queue:[bill?{...structuredClone(bill),editId:bill.id,files:[],originalFiles:bill.files?.length?bill.files:[...(bill.fileName?[{id:bill.id,name:bill.fileName}]:[])],readState:'已入账单据，可修改',declaredTotal:null,reviewed:false}:uxBlankBill(kind)],reading:false};if(!bill)uxBills.queue[0].lines=[{product:'',unit:'个',qty:'',unitPrice:'',amount:'',remark:''}];openModal(bill?'编辑采购单 · 留存修订记录':stock?'批量采购单 · 核对入库':'本户采购单 · 批量读取与核对',`<form id="foUxBill"><div class="ux-bill-workbench"><aside class="ux-bill-queue"><h4>${stock?'采购入库':'本户材料成本'}</h4>${bill?'':`<label>选择多张单 / 多页图片<input type="file" id="uxBillFiles" accept="image/*,.pdf,.xlsx,.xls,.csv" multiple></label><label>文件组织方式<select class="field" id="uxBillGroup"><option value="separate">每个文件是一张单</option><option value="pages">同一张单的多页</option></select></label><div class="fo-actions">${foBtn('读取所选文件','ux-bill-read','',true)}</div>`}<div id="uxBillQueue"></div><p class="ux-bill-status" id="uxBillReading">逐单核对后，可一次保存所有已核对单。</p></aside><section class="ux-bill-review" id="uxBillContent"></section></div><footer class="ux-bill-footer"><button type="button" class="btn" data-action="close-modal">关闭</button><button type="submit" class="btn" name="scope" value="current">保存当前单</button>${bill?'':'<button type="submit" class="btn primary" name="scope" value="all">保存所有已核对单</button>'}</footer></form>`);$('#modalRoot .modal')?.classList.add('rx-wide-modal');uxBillRender();}
  const uxOldBillForm=foBillForm;
  foBillForm=function(kind,stock=false){uxBillOpen(kind,stock);};
  async function uxReadFiles(files,group='separate',replaceIndex=-1){const context=uxBills,f=$('#foUxBill');if(!context||context.reading||!files.length){toast('请选择需要读取的文件');return;}uxQueueState();context.reading=true;f.dataset.reading='yes';const indicator=$('#uxBillReading');try{const queue=group==='pages'?[{...uxBlankBill(context.kind),files:[...files]}]:[...files].map(file=>({...uxBlankBill(context.kind),files:[file]}));for(let i=0;i<queue.length;i++){const b=queue[i];try{for(const file of b.files){indicator.textContent=`正在本机读取 ${i+1}/${queue.length}：${file.name}`;const result=await rxExtract(file);if(!f.isConnected||uxBills!==context)return;if(group==='pages'&&b.billNo&&result.meta?.billNo&&b.billNo!==result.meta.billNo)throw Error('这几页的单号不同，请改选每个文件是一张单分别读取。');b.lines.push(...(result.rows||[]).map(r=>({...factoryOcrBlank(context.kind),product:r.name||'',productCode:r.model||'',spec:r.spec||'',unit:r.unit||'',qty:r.qty??'',unitPrice:r.price??'',amount:r.amount??'',brand:r.brand||'',substrate:r.substrate||'',thickness:r.thickness||'',color:r.color||'',remark:[r.remark||'',r.qtyDerived?'数量由金额÷单价推算，须核对':'',r.amountDerived?'金额由数量×单价推算，须核对':''].filter(Boolean).join('；')})));b.rawText+=(result.text||'')+'\n';if(result.meta?.declaredTotal!=null)b.declaredTotal=Number(result.meta.declaredTotal);if(result.meta?.otherFee)b.otherFee=result.meta.otherFee;if(result.meta?.discount)b.discount=result.meta.discount;for(const key of ['supplier','billNo','date'])if(result.meta?.[key]&&!b[key]||key==='date'&&result.meta?.date)b[key]=result.meta[key];}b.readState=b.lines.length?'已读取，待核对':'未读出明细，可重读或手动补行';}catch(e){b.error=e.message;b.readState='读取失败，原文件仍在队列';}}const retained=context.queue.filter((b,i)=>i!==replaceIndex&&(b.editId||b.saved||!b.error&&b.lines.some(l=>l.product)));context.queue=[...retained,...queue];context.index=retained.length;uxBillRender();indicator.textContent=`已保留 ${queue.length} 张单据，逐单检查再保存。`;}finally{context.reading=false;if(f.isConnected)f.dataset.reading='';}}
  function uxValidateBill(b){if(b.error)return b.error;if(!b.date)return '补填单据日期';let lines=b.lines.filter(l=>String(l.product||'').trim()).map(l=>{const n={...l};for(const k of ['qty','unitPrice','amount'])n[k]=l[k]===''||l[k]==null?null:Number(l[k]);if(n.amount===null&&n.qty!==null&&n.unitPrice!==null)n.amount=foN(n.qty*n.unitPrice);if(n.unitPrice===null&&n.qty>0&&n.amount!==null)n.unitPrice=n.amount/n.qty;return n;});if(!lines.length)return '需要至少一条品名明细';for(const l of lines){if(!String(l.unit||'').trim()||!(l.qty>0)||!(l.amount>0)||![l.qty,l.unitPrice,l.amount].every(Number.isFinite))return `“${l.product}”需要单位、正数量与金额`;if(Math.abs(foN(l.qty*l.unitPrice)-l.amount)>.05)return `“${l.product}”数量×单价与金额不一致，请核对`; }const fee=Number(b.otherFee||0),discount=Number(b.discount||0),sum=foN(lines.reduce((n,l)=>n+l.amount,0));if(![fee,discount].every(n=>Number.isFinite(n)&&n>=0)||discount>sum||sum+fee-discount<=0)return '核对其他费用、折让和单据净额';if(uxBills.stock){const error=feStockConversionError(lines);if(error)return error;}if(b.declaredTotal!=null&&Math.abs(foN(sum+fee-discount)-b.declaredTotal)>.05)return `明细合计${money(sum+fee-discount)}与原单合计${money(b.declaredTotal)}不一致，请补齐漏行或核对费用`;b.lines=lines;b.otherFee=fee;b.discount=discount;b.total=foN(sum+fee-discount);return '';}
  const uxBillSubmit=foExtraSubmit;
  foExtraSubmit=async function(form,v,j){if(form.getAttribute('id')!=='foUxBill')return uxBillSubmit(form,v,j);if(uxBills.reading){toast('文件仍在读取，请稍候');return true;}uxQueueState();const context=uxBills,current=context.queue[context.index],all=form.dataset.saveScope==='all',candidates=(all?context.queue:[current]).filter(b=>!b.saved&&b.reviewed);if(!candidates.length){toast('请先勾选本单核对完成；已保存单不会重复入账');return true;}if(!context.stock&&!j){toast('先打开需要归属的订单');return true;}for(const b of candidates){const error=uxValidateBill(b);if(error){toast(`${b.billNo||b.files[0]?.name||'当前单'}：${error}`);return true;}}
    const savedIds=[];for(const b of candidates){b.newId=b.editId||foId();b.signature=foBillSignature(b,b.lines,context.stock?'inventory':j.id);b.fileHash=b.files.length?await foFileHash(b.files[0]):b.fileHash||'';const duplicates=factoryBills.filter(x=>!x.void&&x.id!==b.editId);if(duplicates.some(x=>(b.fileHash&&x.fileHash===b.fileHash)||x.signature===b.signature||b.billNo&&x.billNo===b.billNo&&x.supplier===b.supplier)){toast('该原单或单号已经登记，请打开原单编辑');return true;}if(savedIds.some(x=>x.signature===b.signature||b.fileHash&&x.fileHash===b.fileHash||b.billNo&&x.billNo===b.billNo&&x.supplier===b.supplier)){toast('所选队列中存在重复单据，请核对后分别保存');return true;}savedIds.push(b);}
    const prepared=[];for(const b of candidates){const old=b.editId?factoryBills.find(x=>x.id===b.editId&&!x.void):null;if(b.editId&&(!old||old.projectId!==j?.id)){toast('原单已变更，请重新打开');return true;}if(old){const booked={};(j.costLines||[]).filter(l=>l.sourceId===old.id).forEach(l=>booked[l.category]=foN((booked[l.category]||0)+l.amount));if(Math.abs(Object.values(booked).reduce((n,a)=>n+a,0)-Number(old.total))>.05){toast('原单已被其他成本调整，请先核对原流水再修订');return true;}const totals=uxBillTotals(b);if(Object.keys(uxCostKeys).some(k=>Number(j[uxCostKeys[k]]||0)+(totals[k]||0)-(booked[k]||0)<-.01)){toast('修订会超过当前成本余额，请先核对冲回记录');return true;}b.booked=booked;}
      const originals=[...(b.originalFiles||[])];for(let i=0;i<b.files.length;i++){const id=i===0&&!old?b.newId:foId();await saveFactoryBillFile(id,b.files[i]);if(!form.isConnected||uxBills!==context)return true;originals.push({id,name:b.files[i].name});}prepared.push({b,old,originals});}
    if(!form.isConnected||uxBills!==context)return true;
    const committed=foCommit(()=>{for(const {b,old,originals} of prepared){const record={id:b.newId,projectId:context.stock?'inventory':j.id,kind:b.kind,supplier:b.supplier||'',billNo:b.billNo||'',date:b.date,lines:structuredClone(b.lines),otherFee:b.otherFee,discount:b.discount,total:b.total,rawText:b.rawText||'',declaredTotal:b.declaredTotal??null,signature:b.signature,fileHash:b.fileHash||'',fileName:old?.fileName||originals[0]?.name||'',files:originals,status:'已核对',modifiedAt:localStamp()};if(old){const snapshot={...structuredClone(old)};delete snapshot.revisions;record.revisions=[...(old.revisions||[]),snapshot];record.revision=(old.revision||0)+1;const totals=uxBillTotals(b);for(const category of Object.keys(uxCostKeys)){const delta=foN((totals[category]||0)-(b.booked[category]||0));if(delta)foCost(j,category,delta,`采购单修订第${record.revision}版 · ${b.supplier} ${b.billNo}`,b.date,old.id);}Object.assign(old,record);}else{factoryBills.push(record);if(context.stock)fePostInvoiceStock(b,b.lines,b.total,b.newId);else{const allocations=feMoneyAlloc(b.discount,b.lines.map(l=>l.amount));b.lines.forEach((l,i)=>foCost(j,uxBillCategoryOf(l,b.kind),foN(l.amount-allocations[i]),`${b.supplier||'供应商待补'} · ${b.billNo} · ${l.product}`,b.date,b.newId));if(b.otherFee)foCost(j,'其他直接成本',b.otherFee,`${b.supplier} · 单据其他费用`,b.date,b.newId);}if(b.paid)foState.cash.push({id:foId(),direction:'out',category:context.stock?'库存采购':b.kind==='五金单'?'五金':'板材',orderId:context.stock?'':j.id,date:b.date,amount:b.total,note:`${b.supplier} · ${b.billNo}`,sourceId:b.newId});}}});
    if(committed){for(const b of candidates){b.saved=true;b.readState=b.editId?'修订已保存':'已入账';}if(context.queue.every(b=>b.saved)||current.editId){uxReleaseBillPreviews();uxBills=null;foDone(current.editId?'单据修改已保存，成本按差额重算；原版本保留':`已保存 ${candidates.length} 张单，原件与成本已关联`);}else{context.index=context.queue.findIndex(b=>!b.saved);uxBillRender();toast(`已保存 ${candidates.length} 张单，请继续核对剩余原单`);}}return true;
  };
  const uxSingleBillSubmit=foExtraSubmit;
  foExtraSubmit=async function(form,v,j){if(form.getAttribute('id')!=='foUxBill')return uxSingleBillSubmit(form,v,j);if(form.dataset.saving)return true;form.dataset.saving='yes';const buttons=[...form.querySelectorAll('button[type="submit"]')];buttons.forEach(b=>b.disabled=true);try{return await uxSingleBillSubmit(form,v,j);}finally{delete form.dataset.saving;buttons.forEach(b=>b.disabled=false);}};
  document.addEventListener('click',e=>{const submit=e.target.closest('#foUxBill button[type="submit"]');if(submit)$('#foUxBill').dataset.saveScope=submit.value;},true);
  document.addEventListener('input',e=>{const row=e.target.closest('#uxBillLines [data-ux-line]');if(row&&e.target.matches('[data-bill-field="qty"],[data-bill-field="unitPrice"]')){const q=row.querySelector('[data-bill-field="qty"]'),p=row.querySelector('[data-bill-field="unitPrice"]'),a=row.querySelector('[data-bill-field="amount"]');if(q.value!==''&&p.value!=='')a.value=foN(Number(q.value)*Number(p.value));}if(e.target.closest('#foUxBill')){uxQueueState();if($('#uxBillTotal')){const b=uxBills.queue[uxBills.index];$('#uxBillTotal').textContent=money(b.lines.reduce((n,l)=>n+Number(l.amount||0),0)+Number(b.otherFee||0)-Number(b.discount||0));}}},true);
  const uxBillAction=action;
  action=function(name,btn){const id=btn.dataset.id||'';if(name==='close-modal'&&$('#foUxBill')){uxReleaseBillPreviews();uxBills=null;}if(name==='ux-bill-read'){uxReadFiles([...(document.getElementById('uxBillFiles')?.files||[])],$('#uxBillGroup').value);return;}if(name==='ux-bill-reread'){uxQueueState();const b=uxBills.queue[uxBills.index];if(!b.files.length){toast('当前记录没有待读取原文件，可直接修改明细');return;}const files=[...b.files];uxReadFiles(files,files.length>1?'pages':'separate',uxBills.index);return;}if(name==='ux-bill-switch'){if(uxBills.reading)return;uxQueueState();uxBills.index=Number(id);uxBillRender();return;}if(name==='ux-bill-add'||name==='ux-bill-remove'){uxQueueState();const b=uxBills.queue[uxBills.index];if(name==='ux-bill-add')b.lines.push({product:'',unit:'个',qty:1,unitPrice:'',amount:'',remark:''});else b.lines.splice(Number(id),1);b.reviewed=false;uxBillRender();return;}if(name==='ux-bill-edit'){const b=factoryBills.find(x=>x.id===id);if(!b||b.void||b.projectId!==foJob()?.id)return;uxBillOpen(b.kind,false,b);return;}if(name==='ux-cost-category'){uxBillCategory=id;rxOrderView='cost';render();return;}if(name==='rx-order-view')uxBillCategory='';return uxBillAction(name,btn);};
  const uxBillPage=factoryOrderDetailPage;
  factoryOrderDetailPage=function(){const t=document.createElement('template');t.innerHTML=uxBillPage();const j=foJob(),section=t.content.querySelector('#feCosts');if(!j||!section)return t.innerHTML;const breakdown=section.querySelector('.fo-cost-breakdown');if(breakdown)breakdown.innerHTML=Object.entries(uxCostKeys).map(([label,key])=>foBtn(`${label==='加工人工'?'人工':label==='其他直接成本'?'其他':label}<b>${money(j[key]||0)}</b><small>查看明细 →</small>`,'ux-cost-category',label)).join('');const table=section.querySelector('.table-wrap table');if(table){table.classList.add('ux-bill-list');const bills=factoryBills.filter(b=>b.projectId===j.id&&(!uxBillCategory||(b.lines||[]).some(l=>uxBillCategoryOf(l,b.kind)===uxBillCategory)));table.querySelector('tbody').innerHTML=bills.map(b=>`<tr class="${b.void?'fo-void':''}"><td>${b.void?'[已冲销] ':''}${b.void?esc(b.supplier||'供应商待补'):foBtn(esc(b.supplier||'供应商待补')+' · '+esc(b.kind),'ux-bill-edit',b.id)}<small class="cell-sub">${esc(b.billNo||'未填单号')} · ${esc(b.date)}${b.revision?' · 修订'+b.revision+'版':''}</small><details><summary>${b.lines?.length||0} 项明细</summary>${(b.lines||[]).map(l=>`<p>${esc(l.product)} · ${l.qty}${esc(l.unit)} · ${money(l.amount)}</p>`).join('')}</details></td><td>${money(b.total)}</td><td>${!b.void?foBtn('查看 / 修改','ux-bill-edit',b.id):''}${(b.files?.length?b.files:b.fileName?[{id:b.id,name:b.fileName}]:[]).map(d=>foBtn('原件：'+esc(d.name),'view-factory-bill-file',d.id)).join('')}${!b.void?foBtn('冲销修正','fo-bill-void',b.id):''}</td></tr>`).join('')||'<tr><td colspan="3" class="fo-empty">此类别暂无采购单，领用及手工成本见下方流水。</td></tr>';if(uxBillCategory)table.insertAdjacentHTML('beforebegin',`<div class="fo-actions">当前类别：${esc(uxBillCategory)} ${foBtn('全部成本','ux-cost-category','')}</div>`);}if(uxBillCategory){const ledger=section.querySelector('details>summary');for(const tr of section.querySelectorAll('details table tbody tr'))if(tr.cells.length>=4&&!tr.textContent.includes(uxBillCategory))tr.hidden=true;}return t.innerHTML;};

  // The same household records feed quotation, payments and construction views.
  rxState.renovation??={categories:['基装','主材','辅材','人工'],products:[],contracts:{}};
  rxState.renovation.directCosts??=[];
  const nwState=()=>rxState.renovation;
  nwState().categoryAliases??={};
  if(!pages.whole.some(p=>p[0]==='nw-finance'))pages.whole.push(['nw-finance','财务管理','￥']);
  let nwQuoteView='category',nwCategory='',nwSiteFilter='',nwLibrarySearch='',nwFinanceMonth=foDate().slice(0,7),nwFinanceBasis='accrual';
  const NW_UNITS=['项','㎡','延米'];
  const NW_WHOLE_COST_CATEGORIES=['主材','人工','其他直接费用'];
  const NW_WHOLE_COST_ALIASES={'材料':'主材','主材成本':'主材','辅材':'其他直接费用','加工人工':'人工','工费':'人工','人工费':'人工','其他':'其他直接费用','其他直接成本':'其他直接费用'};
  function nwUnit(value){const v=String(value||'').trim();if(['按数量','按项','按件','个','套','件'].includes(v))return '项';if(['m²','m2','平方米','平方','㎡'].includes(v))return '㎡';if(['m','米','延米'].includes(v))return '延米';return NW_UNITS.includes(v)?v:'项'}
  function nwWholeCostCategory(value){const v=String(value||'').trim();return NW_WHOLE_COST_ALIASES[v]|| (NW_WHOLE_COST_CATEGORIES.includes(v)?v:'其他直接费用')}
  const nwWhole=()=>module==='whole';
  function nwCategoryOf(value){const names=nwState().categories;if(names.includes(value))return value;const alias=nwState().categoryAliases[value];if(Number.isInteger(alias))return names[alias];if(/主材|门窗|卫浴|橱柜|地砖|墙砖|灯具|定制/.test(value||''))return names[1];if(/人工/.test(value||''))return names[3];if(/辅材/.test(value||''))return names[2];return names[0]}
  const nwLinePrevious=workshopLineRow;
  workshopLineRow=function(x){const t=document.createElement('template');t.innerHTML='<table><tbody>'+nwLinePrevious(x)+'</tbody></table>';const s=t.content.querySelector('[data-category]');if(s){const value=nwCategoryOf(x[8]);s.innerHTML=nwState().categories.map(n=>`<option ${value===n?'selected':''}>${esc(n)}</option>`).join('');}return t.content.querySelector('tr').outerHTML;};
  const nwQuoteLinePrevious=quoteLineRow;
