  const nwBuilderPrevious=workshopBuilder;
  workshopBuilder=function(){const t=document.createElement('template');t.innerHTML=nwBuilderPrevious();const title=t.content.querySelector('.page-head h1');if(title)title.textContent='整装报价工作台';const eyebrow=t.content.querySelector('.eyebrow');if(eyebrow)eyebrow.textContent='整装报价';const intro=t.content.querySelector('.page-head p');if(intro)intro.textContent='直接填项目、单位、数量和单价；基装含常规辅材与人工，额外收费另列。';const nav=t.content.querySelector('.workshop-module-nav');if(nav)nav.innerHTML=tabButtons([['home','工作台'],['base-list','整装报价'],['catalog','产品库'],['additions','增减项'],['templates','报价模板']],quoteSection,'quote-section').replaceAll('data-view=', 'data-section=');const strip=t.content.querySelector('.workshop-category-strip');if(strip)strip.innerHTML=nwState().categories.map(n=>foBtn('＋ '+n,'nw-add-row',n)).join('')+foBtn('从产品库选择','nw-picker')+foBtn('导入 Excel / 图片 / PDF','rx-import','whole')+foBtn('编辑四大类','nw-categories');const sheet=t.content.querySelector('.workshop-sheet');if(sheet)sheet.insertAdjacentHTML('afterbegin',`<div class="nw-controls">${foBtn('按项目分类','nw-quote-view','category',nwQuoteView==='category')}${foBtn('按空间分类','nw-quote-view','space',nwQuoteView==='space')}<select class="field" id="nwCategoryFilter"><option value="">全部四类</option>${nwState().categories.map(n=>`<option ${n===nwCategory?'selected':''}>${esc(n)}</option>`).join('')}</select></div><div class="nw-note">基装综合单价已含常规辅材与人工。辅材、人工两类仅填写约定的额外收费，避免重复计价。</div>`);const add=t.content.querySelector('[data-action="workshop-add-project"]');if(add){add.dataset.action='nw-add-row';add.textContent='＋ 手动新增';}t.content.querySelectorAll('#quoteEmpty [data-action]').forEach(b=>{b.dataset.action='nw-add-row';b.textContent='＋ 手动填写第一项';});const empty=t.content.querySelector('#quoteEmpty b');if(empty)empty.textContent='还没有报价项目';const hint=t.content.querySelector('#quoteEmpty span');if(hint)hint.textContent='手动填写，或从你维护的产品库选择项目。';return t.innerHTML;};
  const nwRecalcPrevious=recalc;
  recalc=function(){nwRecalcPrevious();if(!nwWhole()||!$('#quoteLines'))return;const rows=$$('#quoteLines tr');for(const row of rows){row.hidden=nwQuoteView==='space'?$('[data-room]',row)?.value!==quoteSpace:!!nwCategory&&$('[data-category]',row)?.value!==nwCategory;}if($('#quoteEmpty'))$('#quoteEmpty').hidden=rows.some(r=>!r.hidden);if($('#quoteLineCount'))$('#quoteLineCount').textContent=`当前 ${rows.filter(r=>!r.hidden).length} 项 / 整户 ${rows.length} 项`;const subtotal=$('#workshopSpaceTotal');if(subtotal&&nwQuoteView==='category')subtotal.textContent=money(rows.filter(r=>!r.hidden).reduce((a,r)=>a+Number($('[data-qty]',r)?.value||0)*Number($('[data-price]',r)?.value||0),0));if(subtotal?.parentElement?.firstChild?.nodeType===3)subtotal.parentElement.firstChild.textContent=nwQuoteView==='category'?'当前清单小计 ':'空间小计 ';const summary=$('#workshopRoomSummary');if(summary&&nwQuoteView==='category')summary.innerHTML=nwState().categories.map(n=>`<div><span>${esc(n)}</span><b>${money(rows.filter(r=>$('[data-category]',r)?.value===n).reduce((a,r)=>a+Number($('[data-qty]',r)?.value||0)*Number($('[data-price]',r)?.value||0),0))}</b></div>`).join('');};
  quoteWorkshopHome=function(){return head('QUOTE WORKSHOP · 整装报价','整装报价系统','一张报价清单，按基装、主材、额外辅材、额外人工汇总。',foBtn('＋ 新建报价','new-quote','',true))+`<div class="quote-module-grid">${[['base-list','整装报价','新建、编辑和查看本户整装报价'],['catalog','产品库','自己维护类别、品牌、项目和单价'],['additions','增减项','记录客户确认的增项和减项']].map(([id,n,p])=>`<button class="quote-module-card" data-action="quote-section" data-section="${id}"><strong>${n}</strong><p>${p}</p><span>进入 →</span></button>`).join('')}</div>`;};
  const nwListPrevious=workshopList;
  workshopList=function(){const rows=savedQuotes.filter(q=>q.type==='整装');return head('整装报价','整装报价','所有整装报价在这里管理；原主材报价和历史版本保留。',foBtn('＋ 新建报价','new-quote','',true))+`<div class="quote-list-toolbar"><span>${rows.length} 份报价</span><label class="search">⌕<input id="quoteListSearch" placeholder="搜索客户、小区或报价单号"></label>${workshopRestore?foBtn('继续上次草稿','workshop-resume'):''}</div><div class="quote-saved-grid">${rows.map(q=>`<article class="quote-saved-card"><small>${esc(q.id)}</small><h3>${esc(q.customer)}</h3><p>${esc(q.address||'')} · ${esc(q.time||'')}</p><b>${money(q.amount)}</b><div class="fo-actions">${foBtn('打开编辑','open-saved-quote',q.id)}${foBtn('预览报价单','nw-preview-saved',q.id)}</div></article>`).join('')||'<p class="empty">还没有报价，从本户档案新建报价后会显示在这里。</p>'}</div>`;};
  function nwLibrary(picker=false){const rows=nwState().products.filter(p=>[p.name,p.brand,p.category,p.spec].join(' ').includes(nwLibrarySearch));return head('PRODUCT LIBRARY · 常用项目','产品库','自己录入实际使用的项目与价格；报价时从报价工作台选择。',foBtn('＋ 新增项目','nw-product-new','',true))+`<div class="toolbar"><input class="field" id="nwLibrarySearch" placeholder="搜索名称 / 类别 / 品牌" value="${esc(nwLibrarySearch)}">${foBtn('搜索','nw-library-search')}</div>`+panel('常用报价项目','例如：吊顶 · ㎡ · 每平方单价；类别、品牌和工艺均可手填。',foTable(['类别','项目','品牌 / 型号','单位','单价','工艺 / 备注','操作'],rows.map(p=>`<tr><td>${esc(p.category)}</td><td>${esc(p.name)}</td><td>${esc(p.brand||'')} ${esc(p.model||'')}</td><td>${esc(p.unit)}</td><td>${money(p.price)}</td><td>${esc(p.spec||'')}</td><td>${foBtn(picker?'选择此项':'编辑',picker?'nw-product-pick':'nw-product-new',p.id)}</td></tr>`))+(rows.length?'':'<p class="empty">还没有项目，点击“新增项目”开始录入。</p>'));}
  const nwProductsPrevious=products;products=function(){return nwWhole()?nwLibrary():nwProductsPrevious()};
  const nwQuotePrevious=quote;quote=function(){if(nwWhole()&&quoteSection==='catalog')return nwLibrary();if(nwWhole()&&quoteSection==='major')quoteSection='base-list';return nwQuotePrevious()};
  function nwProductForm(id){const p=nwState().products.find(p=>p.id===id)||{};openModal(p.id?'编辑常用项目':'新增常用项目',foForm('foNwProduct',`<input type="hidden" name="productId" value="${esc(p.id||'')}">`+foField('name','项目名称',p.name||'','text',true)+foField('category','类别（自己填写）',p.category||nwState().categories[0])+foField('brand','品牌（可选）',p.brand||'')+foField('model','型号（可选）',p.model||'')+foSelect('unit','计价单位',NW_UNITS,nwUnit(p.unit||'㎡'))+foField('price','报价单价（元）',p.price??0,'number',true)+foArea('spec','规格 / 工艺 / 备注',p.spec||''),'保存到产品库'));}
  function nwContract(c){return nwState().contracts[c.id]||null}
  function nwFinancial(c){const contract=nwContract(c),income=rxIncome(c),received=income.reduce((n,p)=>n+Number(p.amount||0),0),rawCosts=[...shopLedger.filter(p=>!p.void&&p.type==='支出'&&(p.customerId===c.id||!p.customerId&&rxLegacyMatch(p.project,c))&&(p.costType||p.quoteId)),...nwState().directCosts.filter(p=>!p.void&&p.customerId===c.id)],costs=rawCosts.map(p=>({...p,category:nwWholeCostCategory(p.category||p.costType)})),cost=costs.reduce((n,p)=>n+Number(p.amount||0),0),breakdown=Object.fromEntries(NW_WHOLE_COST_CATEGORIES.map(k=>[k,costs.filter(p=>p.category===k).reduce((n,p)=>n+Number(p.amount||0),0)])),amount=contract?Number(contract.amount):null;return {contract,received,cost,costs,breakdown,amount,outstanding:amount===null?null:Math.max(0,amount-received),margin:amount===null||!costs.length?null:amount-cost}}
