  function nwMonthlyFinance(items){const ids=new Set(items.map(x=>x.c.id)),month=nwFinanceMonth;const receipts=items.flatMap(x=>rxIncome(x.c)).filter(p=>String(p.date||'').startsWith(month));const costs=items.flatMap(x=>x.f.costs).filter(p=>String(p.date||'').startsWith(month));const paid=shopLedger.filter(p=>!p.void&&p.type==='支出'&&String(p.date||'').startsWith(month)&&(ids.has(p.customerId)||!p.customerId&&items.some(x=>rxLegacyMatch(p.project,x.c))));return panel('按月收支','本月到账与实际付款分别统计；本月成本是成本发生额，不等于付款。',`<div class="toolbar"><label>统计月份 <input class="field" id="nwFinanceMonth" type="month" value="${month}"></label></div><div class="cards">${metric('本月实收',money(receipts.reduce((n,p)=>n+Number(p.amount||0),0)),'实际到账日期','￥')}${metric('本月实际付款',money(paid.reduce((n,p)=>n+Number(p.amount||0),0)),'已登记支出流水','￥')}${metric('本月已录成本',money(costs.reduce((n,p)=>n+Number(p.amount||0),0)),'材料、人工等成本发生额','▤')}${metric('本月收款客户',new Set(receipts.map(p=>p.customerId||p.project)).size+' 户','包含已完成客户','♙')}</div>`);}
  const nwStages=[['demolition','拆除 / 新建','开工交底'],['electrical','水电','水电'],['waterproof','防水','防水'],['ceiling','木工 · 吊顶','木工'],['tiling','瓦工 · 瓷砖','瓦工'],['paint','油工 · 墙面乳胶漆','油工'],['material','主材安装','主材安装'],['switches','开关插座','开关插座'],['skirting','踢脚线','踢脚线'],['complete','竣工 / 完成','竣工验收']];
  const nwGetStagesPrevious=getRenovationStages;
  getRenovationStages=function(id){const old=nwGetStagesPrevious(id);if(old.every(s=>s.workflowVersion===2))return old;const record=projectStages.find(r=>r.customerId===id);record.legacyStages??=structuredClone(old);const delivered=sampleCustomers.find(c=>c.id===id)?.stage==='已交付'||old.length>0&&old.every(s=>s.status==='已验收');record.stages=nwStages.map(([key,name,legacy])=>{const item=old.find(s=>s.key===key||s.name===name||s.name===legacy);return {...(item||{status:delivered?'已验收':'未开始',note:delivered?'历史已交付项目，保留完成状态':'',photos:[]}),key,name,workflowVersion:2};});return record.stages;};
  function nwCurrent(c){const steps=getRenovationStages(c.id),done=s=>s.status==='已完成'||s.status==='已验收';return steps.every(done)?'delivered':(steps.find(s=>s.status==='进行中'||s.status==='施工中'||s.status==='待客户验收')||steps.find(s=>!done(s)))?.key;}
  function nwSite(c){const whole=uxCustomerDomain(c)==='whole',steps=whole?getRenovationStages(c.id):[],memos=customerMemos.filter(m=>m.customerId===c.id),logs=projectLogs.filter(p=>p.customerId===c.id).slice().reverse();return `<div class="toolbar">${foBtn('现场拍照','nw-camera','',true)}${foBtn('添加长期提醒','new-customer-memo')}</div>`+panel('本户长期提醒','保留展示，处理完后标记完成；历史记录可继续查看。',memos.map(m=>`<div class="nw-memo ${m.status==='已完成'?'done':''}"><div><b>${esc(m.content)}</b><small class="cell-sub">${esc(m.remindAt||'长期提醒')} · ${esc(m.owner||c.owner)}</small></div>${foBtn(m.status==='已完成'?'恢复提醒':'标记完成','nw-memo-toggle',m.id)}</div>`).join('')||'<p class="empty">暂无提醒</p>')+(whole?panel('工地进程看板','点击工序记录状态；主材安装涵盖门、墙板、柜体等。',`<div class="nw-stage-board">${steps.map((s,i)=>`<button class="nw-stage ${s.status==='已验收'?'done':nwCurrent(c)===s.key?'active':''}" data-action="nw-stage" data-id="${i}"><span>${i+1}. ${esc(s.name)}</span><strong>${esc(s.status)}</strong><small>${esc(s.note||'点击更新')}</small></button>`).join('')}</div>`):panel('定制交付','量房、报价确认和工厂交接使用定制业务流程。',`<p>当前阶段：<b>${esc(c.stage)}</b></p><p>生产进度在工厂订单中记录；本页保留现场照片与安装提醒。</p>`))+panel('现场照片与记录','拍照自动关联本户、当前工序和时间。',`<div class="nw-photo-gallery">${logs.map(p=>`<article>${(p.photoRefs||[]).map(ref=>`<button class="btn" data-action="view-factory-bill-file" data-id="${esc(ref.id)}"><img data-nw-photo="${esc(ref.id)}" alt="${esc(ref.name)}"><span>打开照片</span></button>`).join('')}<b>${esc(p.stageName||'现场记录')}</b><small class="cell-sub">${esc(p.date)} · ${esc(p.content||'')}${!p.photoRefs?.length&&p.photos?.length?' · 历史记录仅存文件名：'+esc(p.photos.join('、')):''}</small></article>`).join('')||'<p class="empty">暂无现场照片</p>'}</div>`);}
  const nwDetailPrevious=customerDetailPage;
  customerDetailPage=function(){const c=sampleCustomers.find(c=>c.id===selectedCustomerId);if(!c)return nwDetailPrevious();if(detailTab==='memos')detailTab='site';const site=uxCustomerDomain(c)==='whole',header=head('CUSTOMER PROJECT · 单户档案',esc(c.name)+' · '+esc(c.community),esc(c.type)+' · 负责人 '+esc(c.owner),foBtn('返回客户列表','customer-detail-back')+foBtn('＋ 新建'+(site?'整装':'定制')+'报价','rx-customer-quote',site?'whole':'custom',true));const tabs=tabButtons([['overview','单户概况'],['quote','单户财务管理'],['site',site?'工地进程':'交付进程'],['followups','跟进记录']],detailTab,'detail-tab');if(detailTab==='quote')return header+tabs+panel('本户报价与版本','选择最终确认的版本作为合同应收；其他历史报价保留。',foTable(['报价单','金额','保存时间','操作'],rxCustomerQuotes(c).map(q=>`<tr><td>${esc(q.id)}</td><td>${money(q.amount)}</td><td>${esc(q.time||'')}</td><td>${foBtn('打开编辑','open-saved-quote',q.id)}${foBtn('预览','nw-preview-saved',q.id)}</td></tr>`)))+rxPaymentPanel(c);if(detailTab==='site')return header+tabs+nwSite(c);const t=document.createElement('template');t.innerHTML=nwDetailPrevious();t.content.querySelector('.page-head')?.remove();t.content.querySelectorAll('.tabs,.demo-tabs').forEach(n=>n.remove());if(detailTab==='overview'){const cards=t.content.querySelectorAll('.cards .metric');if(cards[2])cards[2].outerHTML=`<button class="metric" data-action="nw-house-finance" data-id="${esc(c.id)}"><span class="metric-label">单户财务管理</span><strong class="metric-value">${money(nwFinancial(c).received)}</strong><span class="metric-note">实收 · 查看应收、未收与成本</span></button>`;if(cards[3])cards[3].outerHTML=`<button class="metric" data-action="nw-followups"><span class="metric-label">跟进记录</span><strong class="metric-value">${followupRecords.filter(f=>f.customerId===c.id).length} 条</strong><span class="metric-note">签约前沟通情况与下一步</span></button>`;}t.content.querySelectorAll('[data-action="new-customer-memo"]').forEach(n=>n.remove());return header+tabs+t.innerHTML;};
  projects=function(){const all=sampleCustomers.filter(c=>uxCustomerDomain(c)==='whole'&&['已签约','施工中','已交付'].includes(c.stage)),rows=nwSiteFilter?all.filter(c=>nwCurrent(c)===nwSiteFilter):all;return head('RENOVATION SITE FLOW · 整装工地','整装施工进程','阶段数量与单户工序联动，点击阶段查看对应工地。',foBtn('全部工地','nw-site-filter',''))+panel('施工阶段','拆除新建、水电、防水、木工、瓦工、油工、主材与收尾分别管理。',`<div class="nw-stage-board">${[...nwStages.map(([key,name])=>[key,name]),['delivered','已完成']].map(([key,name])=>`<button class="nw-stage ${nwSiteFilter===key?'active':''}" data-action="nw-site-filter" data-id="${key}"><span>${name}</span><strong>${all.filter(c=>nwCurrent(c)===key).length} 户</strong></button>`).join('')}</div>`)+panel(nwSiteFilter?'本阶段工地':'全部整装工地',rows.length+' 户',foTable(['客户 / 小区','负责人','当前工序','操作'],rows.map(c=>`<tr><td>${esc(c.name)} · ${esc(c.community)}</td><td>${esc(c.owner)}</td><td>${esc(nwStages.find(s=>s[0]===nwCurrent(c))?.[1]||'已完成')}</td><td>${foBtn('进入本户工地','nw-house-site',c.id)}</td></tr>`)));};
  function nwDocument(q){const custom=q.type==='全屋定制',client=sampleCustomers.find(c=>c.id===q.customerId),rows=q.rows||[],groups=custom?[['柜体与基础报价',rows.filter(r=>!r.included&&r.charge!=='upgrade'&&!['门与五金灯光','墙板与收口','安装与服务'].includes(r.category))],['增项与特殊工艺',rows.filter(r=>!r.included&&r.charge!=='upgrade'&&['门与五金灯光','墙板与收口'].includes(r.category))],['安装与服务',rows.filter(r=>!r.included&&r.charge!=='upgrade'&&r.category==='安装与服务')],['五金升级补差',rows.filter(r=>r.charge==='upgrade')],['基础配套（已含）',rows.filter(r=>r.included)]]:nwState().categories.map(n=>[n,rows.filter(r=>nwCategoryOf(r.category)===n)]);let serial=0;const common=custom?['柜体：'+(cqSpecText(q.baseMaterial||{})||'以分项为准'),'柜门：'+(cqSpecText(q.doorMaterial||{})||'以分项为准')].join('；'):'';const sections=groups.filter(([,rs])=>rs.length).map(([title,rs])=>`<section><h2>${esc(title)}</h2><table><colgroup>${(custom?[4,8,13,13,5,7,10,12,28]:[4,8,18,6,9,12,14,29]).map(w=>`<col style="width:${w}%">`).join('')}</colgroup><thead><tr>${['序号','空间','项目名称',...(custom?['尺寸 mm']:[]),'单位','数量','单价','金额','配置 / 工艺 / 备注'].map(n=>`<th>${n}</th>`).join('')}</tr></thead><tbody>${rs.map((r,i)=>{const note=[r.spec,r.remark].filter(Boolean).join('；');return `<tr><td>${++serial}</td><td>${esc(r.room||'—')}</td><td>${esc(r.name)}</td>${custom?`<td>${[r.width,r.height,r.depth].some(Number)?[r.width||'—',r.height||'—',r.depth||'—'].join('×'):'—'}</td>`:''}<td>${esc(r.unit||'项')}</td><td>${Number(r.quantity??r.qty??0).toFixed(2)}</td><td>${r.included?'已含':money(r.price)+'/'+esc(r.unit||'项')}</td><td>${r.included?'已含':money(r.amount)}</td><td class="nw-remarks">${esc(note||'—')}${custom&&i===0&&title==='柜体与基础报价'?`<p><b>统一配置：</b>${esc(common)}</p>`:''}${r.included?'<p>已含于'+esc(r.includedIn||'柜体基础报价')+'</p>':''}</td></tr>`;}).join('')}</tbody></table><p class="workshop-print-subtotal">${esc(title)}小计：${money(rs.reduce((n,r)=>n+Number(r.amount||0),0))}</p></section>`).join('');return `<article class="quote-print-document nw-document"><header><div><h1><img class="brand-document-logo" src="assets/brand/yijiang-logo-horizontal.png?v=20261017132149" alt="艺匠全屋定制">艺匠全屋定制</h1><span>${custom?'全屋定制':'整装'} · 客户报价单</span></div><div><small>报价单号</small><br><b>${esc(q.id||'草稿')}</b></div></header><div class="nw-document-meta"><div><small>客户姓名</small><b>${esc(client?.name||q.customer||'待确认')}</b></div><div><small>小区地址</small><b>${esc(q.address||client?.community||'待确认')}</b></div><div><small>设计师 / 日期</small><b>${esc(q.owner||'')} · ${esc(q.date||'')}</b></div></div><div class="nw-document-body">${sections||'<p>添加项目后生成报价明细</p>'}<div class="nw-document-total"><div>${custom?'优惠减免：−'+money(q.discount||0)+'　运输：'+money(q.deliveryFee||0)+'　安装：'+money(q.installFee||0):'管理费：'+money(q.managementAmount||0)+'　税费：'+money(q.taxAmount||0)}</div><div>客户报价合计<br><strong>${money(q.amount||0)}</strong></div></div><p class="nw-remarks">${custom?'基础报价含双方确认的常规配套，五金升级仅按差额计费。':'基装综合单价已含常规辅材和人工；辅材与人工类别仅列额外收费。'} ${esc(q.requirements||'')}<br>未含项目：${esc(q.exclusions||'双方另行确认')}　有效期：${esc(q.validity||'待确认')}</p></div><footer class="nw-signatures"><span>客户签字：_______________</span><span>经办人：_______________</span></footer></article>`;}
  cqLiveDocument=function(q){return nwDocument(q)};
  cqPrint=function(q){if(!q.rows?.length){toast('请先添加报价项目');return;}openModal('客户报价单',`<div class="modal-body">${nwDocument(q)}</div><div class="modal-foot">${foBtn('返回','close-modal')}${foBtn('打印 / 保存 PDF','print-quote-now','',true)}</div>`);$('#modalRoot .modal')?.classList.add('nw-document-modal');};
  const nwPrintPrevious=quotePrintPreview;
