  function crSchemeCard(s){return `<article class="cr-scheme-card"><div><span class="cr-eyebrow">${s.archived?'已停用':'常用搭配'}</span><h3>${esc(s.name)}</h3><p>柜体：${esc(cqSpecText(s.baseMaterial)||'待确认')}</p><p>柜门：${esc(cqSpecText(s.doorMaterial)||'待确认')}</p></div><div class="cr-scheme-rates"><span>投影 <b>${s.projectedPrice?money(s.projectedPrice)+'/㎡':'逐户核价'}</b></span><span>延米 <b>${s.linearPrice?money(s.linearPrice)+'/米':'逐户核价'}</b></span></div><small>${esc(s.note||'常规铰链、滑道包含于基础柜体价；增项与升级另核。')}</small><div class="cr-scheme-actions">${!s.archived?`<button class="btn small" data-action="cr-use" data-id="${esc(s.id)}">选用到当前草稿</button>`:''}<button class="btn small" data-action="cr-archive" data-id="${esc(s.id)}">${s.archived?'恢复使用':'停用搭配'}</button></div></article>`}
  function crSchemeLibrary(){return `<section class="cr-library"><div class="workshop-panel-heading"><div><b>常用柜体与柜门搭配</b><p>将确认过的配置存为方案，下一户选用后再核价。</p></div><button class="btn" data-action="cr-save">保存当前搭配</button></div><div class="cr-scheme-grid">${cqState.schemes.map(crSchemeCard).join('')||'<div class="cr-empty"><b>先确认一户的材料搭配</b><p>进入报价，选择柜体与柜门、填客户单价，再保存为常用方案。</p><button class="btn small" data-action="cq-resume">打开当前草稿</button></div>'}</div></section>`}
