  function crRefreshBasis(){const q=cqState.draft||{};if(!$('#cqRoomNav'))return;$('#cqBasisSummary').innerHTML=esc(cqSpecText(q.baseMaterial||{})||'柜体板材待选')+'<br>柜门：'+esc(cqSpecText(q.doorMaterial||{})||'材料与是否包含待确认');$('#cqProjectedPrice').value=q.projectedPrice||0;$('#cqLinearPrice').value=q.linearPrice||0;$('.cr-basis-tools b').textContent=cqState.schemes.filter(s=>!s.archived).length;recalc()}
  function crSaveQuote(){recalc();const q=quoteDraftFromPage();if(!q.customerId||!q.rows.length){toast('请选择客户并添加报价项目');return}if(q.rows.length!==cqRows().length){toast('还有未命名项目，请补齐名称后保存');return}if(q.discount>q.subtotal){toast('优惠不能大于分项合计');return}if(q.rows.some(r=>r.quantity<=0||(!r.included&&r.price<=0))){toast('请补齐尺寸、数量和客户单价；升级项核定补差，包含项目标为已含');return}const previousQuotes=savedQuotes.slice(),previousState=crClone(cqState);let demoBefore,cqBefore;try{demoBefore=localStorage.getItem(demoStorageKey);cqBefore=localStorage.getItem(cqStorage)}catch{toast('无法读取本机存储，请导出备份');return}const idx=savedQuotes.findIndex(x=>x.id===q.id&&x.type==='全屋定制');if(idx<0)savedQuotes.unshift(q);else savedQuotes[idx]=q;cqState.draft=crClone(q);if(!persistDemo()||!cqPersist()){savedQuotes.splice(0,savedQuotes.length,...previousQuotes);cqState=previousState;try{if(demoBefore===null)localStorage.removeItem(demoStorageKey);else localStorage.setItem(demoStorageKey,demoBefore);if(cqBefore===null)localStorage.removeItem(cqStorage);else localStorage.setItem(cqStorage,cqBefore)}catch{toast('存储恢复未完成，请导出备份后处理本机空间')}$('#cqDraftStatus').textContent='本版报价未完整保存，请导出备份后再离开';return}quoteDraftId=q.id;cqSection='list';render();toast('定制报价已保存，可打开编辑或复制新版本')}
  function crSaveDialog(){if(module!=='custom')return;cqEnsureBuilder();const q=quoteDraftFromPage();openModal('保存常用柜体与柜门搭配',`<form id="crSaveScheme"><div class="modal-body"><p>仅保存材料配置和当前核定的客户单价，客户、尺寸、数量及原单资料留在本户报价中。</p><div class="form-grid"><label class="full">方案名称<input class="field" name="name" maxlength="60" placeholder="如：颗粒柜体＋PET门板 · 零售" required></label><label class="full">方案备注（选用后逐户确认约定）<textarea class="field" name="note" maxlength="500" placeholder="约定常规五金型号、柜门包含范围、适用条件"></textarea></label></div><div class="cr-config-review"><p>柜体：${esc(cqSpecText(q.baseMaterial)||'待补充')}</p><p>柜门：${esc(cqSpecText(q.doorMaterial)||'待补充')}</p><p>客户投影价：${q.projectedPrice?money(q.projectedPrice)+'/㎡':'待核定'}　延米价：${q.linearPrice?money(q.linearPrice)+'/米':'待核定'}</p></div></div><div class="modal-foot"><button type="button" class="btn" data-action="close-modal">取消</button><button class="btn primary">保存搭配</button></div></form>`)}
  const crAction=action;
  action=function(name,btn){
    if(module!=='custom')return crAction(name,btn);
    if(name==='cr-picker'){crPicker();return}
    if(name==='cr-save'){crSaveDialog();return}
    if(name==='save-quote'&&$('#cqRoomNav')){crSaveQuote();return}
    if(name==='cr-archive'){const id=btn.dataset.id;if(crCommit(()=>{const s=cqState.schemes.find(x=>x.id===id);if(s)s.archived=!s.archived})){if($('#cqRoomNav')){$('#modalRoot').innerHTML='';recalc()}else render();toast('搭配使用状态已保存')}return}
    if(name==='cr-use'){const selected=cqState.schemes.find(s=>s.id===btn.dataset.id&&!s.archived);if(!selected){toast('此搭配已停用，请重新选择');return}const s=crClone(selected);cqEnsureBuilder();const q=quoteDraftFromPage();if(!crCommit(()=>{cqState.draft={...q,baseMaterial:crClone(s.baseMaterial),doorMaterial:crClone(s.doorMaterial),projectedPrice:s.projectedPrice,linearPrice:s.linearPrice}}))return;$('#modalRoot').innerHTML='';crRefreshBasis();toast('常用搭配已选用，后续新增项目使用此配置');return}
    return crAction(name,btn)
  };
  document.addEventListener('submit',e=>{if(e.target.id!=='crSaveScheme')return;e.preventDefault();e.stopImmediatePropagation();const f=e.target,d=Object.fromEntries(new FormData(f)),name=String(d.name||'').trim(),q=quoteDraftFromPage();if(!name||cqState.schemes.some(s=>s.name===name)){toast('请填写不同的方案名称，已停用的名称也保留');return}if(!cqSpecText(q.baseMaterial||{})&&!cqSpecText(q.doorMaterial||{})){toast('请先选择或填写柜体 / 柜门材料配置');return}if(![q.projectedPrice,q.linearPrice].every(n=>Number.isFinite(n)&&n>=0)){toast('客户单价必须是有效的非负数');return}const s={id:'CQS-'+Date.now()+'-'+Math.random().toString(36).slice(2,7),name,note:String(d.note||'').trim(),baseMaterial:crClone(q.baseMaterial||{}),doorMaterial:crClone(q.doorMaterial||{}),projectedPrice:q.projectedPrice,linearPrice:q.linearPrice,createdAt:localStamp(),archived:false};if(crCommit(()=>{cqState.draft=q;cqState.schemes.push(s)})){$('#modalRoot').innerHTML='';crRefreshBasis();toast('常用搭配已保存，可用于后续客户报价')}},true);
  function crCharges(q){const out={base:0,extra:0,upgrade:0,included:0};for(const r of q.rows||[]){if(r.included||r.charge==='included'){out.included++;continue}const key=r.charge==='upgrade'?'upgrade':['门与五金灯光','墙板与收口','安装与服务'].includes(r.category)?'extra':'base';out[key]+=Math.round(Number(r.amount||0)*100)}return out}
  function crChargeSummary(q,customer=false){const t=crCharges(q);return `<section class="cr-charge-summary ${customer?'cr-customer-summary':''}"><div class="cr-summary-heading"><b>这份报价怎么组成</b><span>已含配套不重复加价</span></div><div class="cr-charge-grid"><div><small>柜体与基础项目</small><b>${money(t.base/100)}</b></div><div><small>增项与服务</small><b>${money(t.extra/100)}</b></div><div><small>五金升级补差</small><b>${money(t.upgrade/100)}</b></div><div><small>已含配套列示</small><b>${t.included} 项</b></div></div><p>常规铰链、滑道按清单约定包含；灯带、玻璃门和特殊工艺单列。${customer?'升级按约定的差额计费，原基础配套不再重复收费。':'升级项只填写补差金额，不填写升级件全价。'}</p></section>`}
  const crRecalc=recalc;
  recalc=function(){crRecalc();if(module!=='custom'||!$('#cqRoomNav'))return;let el=$('#crChargeSummary');if(!el){el=document.createElement('div');el.id='crChargeSummary';$('#cqRoomSummary').after(el)}el.innerHTML=crChargeSummary(quoteDraftFromPage());cqRows().forEach(r=>{const charge=$('[data-included]',r).value,note=$('.cq-charge-note',r);if(note)note.textContent=charge==='upgrade'?'填升级差额，不填升级件全价':charge==='included'?'已计入基础价，无需再收费':'按客户确认单价收费'})};
