        const paymentData=d.wip?[[65800,'2026-10-02','定金/首付款']]:[[59000,'2026-07-10','定金/首付款'],[35400,'2026-07-25','二期/水电款'],[17700,'2026-08-10','三期/中期款'],[5900,'2026-08-30','尾款/质保金']];for(let i=0;i<paymentData.length;i++){const [p_amount,p_paid_at,p_note]=paymentData[i],marker='STEP2-DEMO-'+d.phone+'-到账-'+i;if(!rc.payments.some(x=>x.order_id===order.id&&x.note===marker))await call('reno_record_payment',{p_order_id:order.id,p_amount,p_paid_at,p_method:'银行转账',p_voucher_path:null,p_note:marker},'payment:'+d.phone+':'+i)}
