  const rsTable=(headers,rows)=>`<div class="table-wrap"><table><thead><tr>${headers.map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${rows||`<tr><td colspan="${headers.length}">暂无记录</td></tr>`}</tbody></table></div>`;
  function rsForemanHome(){rsStart();const cards=rs.orders.map(o=>`<article class="rs-site-card"><div class="rs-site-top"><span class="tag blue">${esc(o.status||'施工中')}</span><span>${esc(o.current_stage||'待开工')}</span></div><h2>${esc(o.customer_name)}</h2><p>${esc(o.community)} ${esc(o.unit||'')}</p><p>${esc(o.layout||'')} · ${o.area_m2||'—'}㎡</p><button class="btn primary rs-wide" data-action="rs-order-open" data-id="${o.id}">查看工地进度</button></article>`).join('');return head('我的工地','整装施工进程','仅显示分配给本人的项目；此工作台只展示施工信息。')+rsBanner()+`<div class="rs-site-grid">${cards||(!rs.busy?'<p class="empty">目前没有分配给您的整装工地</p>':'')}</div>`}
  function rsForemanOrder(){const o=rsOrder(rs.selectedOrder);if(!o)return rsForemanHome();const stages=rsStages(o.id);return head(`${esc(o.customer_name)} · 工地进度`,'我的工地','施工节点与照片记录；页面不包含金额信息。',`<button class="btn" data-page="projects">返回工地</button>`)+rsBanner()+`<div class="rs-site-card"><h2>${esc(o.community)} ${esc(o.unit||'')}</h2><p>${esc(o.layout||'')} · ${o.area_m2||'—'}㎡</p><div class="rs-stage-list">${stages.map(s=>`<article class="rs-stage-card"><div class="rs-stage-heading"><b>${s.seq}. ${esc(s.name)}</b><span class="tag ${s.status==='已验收'?'green':'blue'}">${esc(s.status)}</span></div><p>计划 ${esc(s.planned_date||'—')} · 实际 ${esc(s.actual_date||'未登记')}</p><p>${esc(s.required_photo_hint||'')}</p><p>${esc(s.note||'')}</p><div class="rs-stage-actions"><button class="btn primary" data-action="rs-stage-edit" data-id="${s.id}">更新节点</button><button class="btn" data-action="rs-photo-upload" data-id="${s.id}">上传照片</button></div>${rs.photos.filter(p=>p.order_stage_id===s.id).map(p=>`<button class="btn small" data-action="rs-photo-view" data-id="${esc(p.storage_path)}">查看照片 · ${esc(p.uploaded_at||'')}</button>`).join('')}</article>`).join('')||'<p class="empty">尚无施工节点</p>'}</div></div>`}
