  function rsDesignerCustomers(){rsStart();return head('客户与跟进','我的整装客户','可创建客户并维护跟进记录。',`<button class="btn primary" data-action="rs-customer-new">＋ 新建客户</button>`)+rsBanner()+panel('客户档案',`${rs.customers.length} 户`,rsTable(['客户','电话','小区','户型 / 面积','状态 / 阶段','下次联系','操作'],rs.customers.map(c=>`<tr><td><button class="btn link-button" data-action="rs-customer-open" data-id="${c.id}">${esc(c.name)}</button></td><td>${esc(c.phone||'')}</td><td>${esc(c.community)} ${esc(c.unit||'')}</td><td>${esc(c.layout||'')} · ${c.area_m2||'—'}㎡</td><td>${esc(c.business_status)} · ${esc(c.stage||'')}</td><td>${esc(c.next_followup_at||'')}</td><td><button class="btn small" data-action="rs-customer-open" data-id="${c.id}">打开</button></td></tr>`).join('')))}
  function rsDesignerQuotes(){rsStart();return head('整装报价','报价历史','显示本人客户的报价版本与销售金额。',`<button class="btn" data-page="customers">选择客户后新建报价</button>`)+rsBanner()+panel('报价列表',`${rs.quotes.length} 个版本`,rsTable(['客户','报价单号','版本','状态','报价日期','报价总额','操作'],rs.quotes.map(q=>`<tr><td>${esc(rsCustomer(q.customer_id)?.name||'')}</td><td>${esc(q.quote_no)}</td><td>V${q.version}</td><td>${esc(q.status)}</td><td>${esc(q.quote_date||'')}</td><td>${rsMoney(q.total_amount)}</td><td>${q.status==='草稿'?`<button class="btn small" data-action="rs-quote-edit-draft" data-id="${q.id}">编辑草稿</button>`:'只读'}</td></tr>`).join('')))}
