    return head(`${esc(c.name)} · ${esc(c.community)}`,'客户档案',`${esc(c.business_status)} · ${esc(c.stage||'')}`,`<button class="btn" data-page="customers">返回客户</button><button class="btn" data-action="rs-followup-new" data-id="${c.id}">＋ 跟进</button><button class="btn primary" data-action="rs-quote-new" data-id="${c.id}">＋ 新建报价</button>`)+rsBanner()+`<nav class="rs-dossier-nav"><a href="#rsProfile">客户资料</a><a href="#rsQuotes">报价历史</a><a href="#rsOrders">合同、收款与工地进度</a><a href="#rsFollowups">跟进记录</a></nav><div id="rsProfile" class="rs-dossier-grid">${panel('客户基本信息',`${esc(c.phone||'无电话')} · ${esc(c.layout||'户型未填')} · ${c.area_m2||'—'}㎡`,`${esc(c.community)} ${esc(c.unit||'')}<br>当前阶段：${esc(c.business_status)} / ${esc(c.stage||'')}`)}${assignment}${profilePanel}</div><div id="rsQuotes">${panel('报价历史版本','既有报价可查看；草稿可继续编辑并保存到云端。',rsTable(['报价单号','版本','状态','报价金额','操作'],quoteRows))}</div><div id="rsOrders">${panel('合同订单、收款与工地进度',`${orders.length} 单；这里只显示销售、收款和施工信息。`,orders.map(o=>`<section class="rs-dossier-order"><header><div><strong>${esc(o.status)} · ${esc(o.current_stage||'待开工')}</strong><small>${esc(o.signed_at||'')}</small></div><button class="btn primary" data-action="rs-order-open" data-id="${o.id}">打开订单档案</button></header></section>`).join('')||'<p class="empty">该客户尚未签约下单</p>')}</div><div id="rsFollowups">${panel('跟进时间线','跟进记录按时间追加保存。',rsTable(['时间','跟进内容','下次联系'],fups.map(f=>`<tr><td>${esc(f.followup_at||'')}</td><td>${esc(f.content)}</td><td>${esc(f.next_followup_at||'')}</td></tr>`).join('')))}</div>`;
