  function rsQuotePreview(q){if(!q)return;const c=rsCustomer(q.customer_id),items=rs.quoteItems.filter(i=>i.quote_id===q.id),sections=[...new Set(items.map(i=>i.section||'其他增项'))];openModal('艺匠全屋定制 · 客户报价预览',`<div class="modal-body rs-quote-preview"><header><h2>装修工程预算书</h2><p>${esc(c?.name||'')} · ${esc(c?.community||'')} ${esc(c?.unit||'')}</p><p>${esc(q.quote_no||'')} · V${q.version} · ${esc(q.quote_date||'')} · ${esc(q.status)}</p></header>${sections.map(section=>`<section><h3>${esc(section)}</h3>${rsTable(['项目','单位','数量','单价','合价','工艺备注'],items.filter(i=>(i.section||'其他增项')===section).map(i=>`<tr><td>${esc(i.item_name)}</td><td>${esc(i.unit)}</td><td>${Number(i.quantity||0)}</td><td>${rsMoney(i.unit_price)}</td><td>${rsMoney(i.amount)}</td><td>${esc(i.workmanship_note||i.note||'')}</td></tr>`).join(''))}</section>`).join('')}<h2 class="rs-preview-total">报价总额 ${rsMoney(q.total_amount)}</h2></div><div class="modal-foot"><button class="btn" data-action="close-modal">关闭</button></div>`)}
  const rsForm=(title,id,body,button)=>openModal(title,`<form id="${id}"><div class="modal-body"><div class="form-grid">${body}</div></div><div class="modal-foot"><button type="button" class="btn" data-action="close-modal">取消</button><button class="btn primary">${button}</button></div></form>`);
  const rsCustomerForm=()=>rsForm('新建整装客户','renoStaffCustomer',`<label>客户姓名<input class="field" name="name" required></label><label>联系电话<input class="field" name="phone"></label><label>小区<input class="field" name="community"></label><label>房号<input class="field" name="unit"></label><label>户型<input class="field" name="layout"></label><label>面积㎡<input class="field" name="area_m2" type="number" min="0"></label><label>客户来源<select class="field" name="source">${['到店','老客转介','抖音','小区驻点','电话咨询','装饰公司渠道','其他'].map(x=>`<option>${x}</option>`)}</select></label><label>设计师姓名<input class="field" name="designer_display_name" placeholder="当前设计师姓名"></label><label>分配工长<select class="field" name="foreman_id"><option value="">暂未分配</option>${rs.assignments.filter(x=>x.role_name==='foreman').map(x=>`<option value="${x.user_id}">${esc(x.display_name)}</option>`).join('')}</select><input class="field" name="foreman_display_name" placeholder="工长姓名可手动填写"></label><label>下次联系<input class="field" name="next_followup_at" type="date"></label><label class="full">需求<textarea class="field" name="needs"></textarea></label><label class="full">量房记录<textarea class="field" name="survey_notes"></textarea></label>`,'保存客户');
