  function rsQuoteForm(id){const c=rsCustomer(id),n=Math.max(1,...rs.quotes.filter(q=>q.customer_id===id).map(q=>Number(q.version)+1));rsForm('新建整装报价','renoStaffQuote',`<input type="hidden" name="customer_id" value="${id}"><label>报价单号<input class="field" name="quote_no" value="YJ-${Date.now()}" required></label><label>版本<input class="field" name="version" type="number" min="1" value="${n}"></label><label>报价日期<input class="field" name="quote_date" type="date" value="${new Date().toISOString().slice(0,10)}"></label><label>设计费<input class="field" name="design_fee" type="number" min="0" value="0"></label><label>税金<input class="field" name="tax" type="number" min="0" value="0"></label><label>优惠<input class="field" name="discount" type="number" min="0" value="0"></label><div class="full"><h3>${esc(c?.name||'')} 报价明细</h3><div class="rs-quote-line"><input class="field" name="space" placeholder="空间" value="全屋"><input class="field" name="category" placeholder="类别" value="基础施工"><input class="field" name="item_name" placeholder="项目名称" required><input class="field" name="spec" placeholder="工艺 / 规格"><input class="field" name="unit" placeholder="单位" value="项"><input class="field" name="quantity" type="number" min="0" step="0.01" value="1"><input class="field" name="unit_price" type="number" min="0" step="0.01" value="0"></div><button type="button" class="btn small" data-action="rs-add-quote-line">＋ 添加一行</button></div>`,'保存报价')}
