  const rsRenderPrevious=render;render=function(){if(module==='whole'&&role==='foreman'){if(!['home','projects','reno-order-detail'].includes(page))page='projects';renderNav();$('#roleSelect').value=role;$('#view').innerHTML=(page==='reno-order-detail'?rsForemanOrder():rsForemanHome());return}if(module==='whole'&&role==='sales'&&['home','customers','quotes','projects','customer-detail','reno-order-detail','reno-quote-editor'].includes(page)){if(page==='reno-quote-editor')rsStart();renderNav();$('#roleSelect').value=role;$('#view').innerHTML=page==='customers'?rsDesignerCustomers():page==='quotes'?rsDesignerQuotes():page==='projects'?rsDesignerProjects():page==='customer-detail'?rsDesignerCustomer():page==='reno-order-detail'?rsDesignerOrder():page==='reno-quote-editor'?rsQuoteEditorPage():rsDesignerHome();if(page==='reno-quote-editor'&&rs.loaded){rsRestoreDraft();rsQuoteTotals(document.querySelector('#renoStaffQuote'));document.querySelectorAll('#renoStaffQuote [data-rs-note]').forEach(x=>{x.style.height='auto';x.style.height=x.scrollHeight+'px'})}return}rsRenderPrevious()};
  const rsActionPrevious=action;action=function(name,btn){const id=btn?.dataset.id||'';if(name==='rs-refresh'){rs.loaded=false;rsLoad();return}if(name==='rs-customer-new'){rsCustomerForm();return}if(name==='rs-customer-open'){rs.selectedCustomer=id;rs.profile=null;rs.profileCustomer='';rs.profileError='';page='customer-detail';render();queueMicrotask(()=>rsLoadProfile(id));return}if(name==='rs-profile-reload'){rsLoadProfile(id,true);return}if(name==='rs-quote-preview'){rsQuotePreview(rs.quotes.find(q=>q.id===id));return}if(name==='rs-customer-document'){rsCustomerDocumentForm(id);return}if(name==='rs-customer-document-view'){const c=rsClient();c.storage.from('reno-files').createSignedUrl(id,120).then(({data,error})=>{if(error)throw error;window.open(data.signedUrl,'_blank','noopener')}).catch(e=>toast(e?.message||String(e)));return}if(name==='rs-order-open'){rs.selectedOrder=id;page='reno-order-detail';render();return}if(name==='rs-followup-new'){rsFollowupForm(id);return}if(name==='rs-quote-edit-draft'){const q=rs.quotes.find(x=>x.id===id);if(q){rs.selectedQuote=id;rs.selectedCustomer=q.customer_id;page='reno-quote-editor';render()}return}if(name==='rs-quote-new'){rs.selectedQuote='';rsQuoteForm(id);return}if(name==='rs-payment-new'){rsPaymentForm(id);return}if(name==='rs-stage-edit'){rsStageForm(id);return}if(name==='rs-photo-upload'){const input=document.createElement('input');input.type='file';input.accept='image/jpeg,image/png,image/webp';input.onchange=()=>{const f=input.files?.[0],s=rs.stages.find(x=>x.id===id),o=rsOrder(s?.order_id);if(!f||!s||!o)return;if(f.size>20971520){toast('照片不能超过20MB');return}const today=new Date().toISOString().slice(0,10),safe=f.name.replace(/[^a-zA-Z0-9._-]/g,'_'),path=`reno/${o.customer_id}/${o.id}/stage-${s.seq}/${today}/${crypto.randomUUID()}-${safe}`;const c=rsClient();c.storage.from('reno-files').upload(path,f,{contentType:f.type,upsert:false}).then(({error})=>{if(error)throw error;return rsRpc('reno_foreman_upload_photo',{p_stage_id:s.id,p_storage_path:path,p_file_name:f.name,p_file_size:f.size})}).then(()=>rsLoad()).catch(e=>toast(e?.message||String(e)))};input.click();return}if(name==='rs-photo-view'){const c=rsClient();c.storage.from('reno-files').createSignedUrl(id,120).then(({data,error})=>{if(error)throw error;window.open(data.signedUrl,'_blank','noopener')}).catch(e=>toast(e.message));return}if(name==='rs-add-quote-line'){const section=btn.dataset.section||rsQuoteSections[0];btn.closest('[data-rs-section]').querySelector('.reno-quote-rows').insertAdjacentHTML('beforeend',rsQuoteLine(section));rsQuoteTotals($('#renoStaffQuote'));rsQueue($('#renoStaffQuote'));return}return rsActionPrevious(name,btn)};
  const rsSubmitPrevious=foExtraSubmit;foExtraSubmit=async function(form,v,j){
    if(!form.id?.startsWith('renoStaff'))return rsSubmitPrevious(form,v,j);
    try{
      let result;
      if(form.id==='renoStaffProfile'){
        await rsRpc('reno_save_customer_profile',{p_customer_id:v.customer_id,p_needs:v.needs,p_survey_notes:v.survey_notes,p_preferences:v.preferences,p_request_id:crypto.randomUUID()});
        toast('客户资料已保存到云端');await rsLoadProfile(v.customer_id,true);return true;
      }
      if(form.id==='renoStaffAssignment'){
        await rsRpc('reno_assign_customer_staff',{p_customer_id:form.dataset.customer,p_designer_id:null,p_foreman_id:v.foreman_id||null,p_designer_name:rs.profile?.designer_display_name||'',p_foreman_name:v.foreman_display_name||'',p_request_id:crypto.randomUUID()});
        toast('工长分配已同步');$('#modalRoot').innerHTML='';rs.loaded=false;await rsLoad();await rsLoadProfile(form.dataset.customer,true);return true;
      }
      if(form.id==='renoStaffDocument'){
        const file=form.elements.file.files?.[0];if(!file)throw Error('请选择资料文件');if(file.size<=0||file.size>20971520)throw Error('资料必须小于20MB');if(!['image/jpeg','image/png','image/webp','application/pdf'].includes(file.type))throw Error('仅支持 JPG、PNG、WebP 或 PDF');
        const date=new Date().toISOString().slice(0,10),safe=file.name.replace(/[^a-zA-Z0-9._-]/g,'_'),path=`reno/${v.customer_id}/quote/${date}/${crypto.randomUUID()}-${safe}`,client=rsClient(),upload=await client.storage.from('reno-files').upload(path,file,{contentType:file.type,upsert:false});if(upload.error)throw upload.error;
        await rsRpc('reno_register_customer_document',{p_customer_id:v.customer_id,p_kind:v.kind,p_file_name:file.name,p_storage_path:path,p_mime_type:file.type,p_file_size:file.size,p_note:v.note||'',p_request_id:crypto.randomUUID()});
        toast('客户资料已上传');$('#modalRoot').innerHTML='';await rsLoadProfile(v.customer_id,true);return true;
      }
      if(form.id==='renoStaffCustomer'){
        result=await rsRpc('reno_save_customer',{p_customer_id:null,p_data:{...v,area_m2:v.area_m2||null,designer_id:null,foreman_id:v.foreman_id||null,business_type:'整装',business_status:'线索',stage:'线索'},p_request_id:crypto.randomUUID()});
        await rsRpc('reno_assign_customer_staff',{p_customer_id:result.id,p_designer_id:null,p_foreman_id:v.foreman_id||null,p_designer_name:v.designer_display_name,p_foreman_name:v.foreman_display_name,p_request_id:crypto.randomUUID()});
        await rsRpc('reno_save_customer_profile',{p_customer_id:result.id,p_needs:v.needs,p_survey_notes:v.survey_notes,p_preferences:'',p_request_id:crypto.randomUUID()});
      }
      if(form.id==='renoStaffFollowup')result=await rsRpc('reno_record_followup',{p_customer_id:v.customer_id,p_content:v.content,p_followup_at:v.followup_at?new Date(v.followup_at).toISOString():null,p_next_followup_at:v.next_followup_at||null,p_request_id:crypto.randomUUID()});
      if(form.id==='renoStaffQuote'){const rows=[...form.querySelectorAll('.rs-quote-line')],items=rows.map((r,i)=>({line_no:i+1,space:r.querySelector('[name=space]').value,category:r.querySelector('[name=category]').value,item_name:r.querySelector('[name=item_name]').value,spec:r.querySelector('[name=spec]').value,unit:r.querySelector('[name=unit]').value,quantity:Number(r.querySelector('[name=quantity]').value),unit_price:Number(r.querySelector('[name=unit_price]').value),in_package:false,note:''})).filter(x=>x.item_name);result=await rsRpc('reno_create_quote',{p_customer_id:v.customer_id,p_quote_no:v.quote_no,p_version:Number(v.version),p_quote_date:v.quote_date||null,p_design_fee:Number(v.design_fee||0),p_tax:Number(v.tax||0),p_discount:Number(v.discount||0),p_items:items,p_request_id:crypto.randomUUID()})}
      if(form.id==='renoStaffStage')result=await rsRpc('reno_foreman_update_stage',{p_stage_id:v.stage_id,p_status:v.status,p_actual_date:v.actual_date||null,p_accepted:v.accepted==='true',p_note:v.note,p_request_id:crypto.randomUUID()});
      if(form.id==='renoStaffPayment')result=await rsRpc('reno_record_payment',{p_order_id:v.order_id,p_amount:Number(v.amount),p_paid_at:v.paid_at,p_method:v.method,p_voucher_path:null,p_note:v.note||'',p_request_id:crypto.randomUUID()});
      $('#modalRoot').innerHTML='';toast(result?.status==='received'?'收款已登记':'已保存到云端');rs.loaded=false;await rsLoad();return true;
    }catch(e){toast(e?.message||String(e));return true}
  };
   const rsQuoteSections=['拆除新建','水电暖改造','防水','木工吊顶','泥瓦铺贴','墙面油工','安装主材','其他增项'];
   function rsQuoteLine(section){const options=rs.quoteLibrary.filter(x=>x.section===section&&x.is_active).map(x=>`<option value="${x.id}" data-name="${esc(x.item_name)}" data-unit="${esc(x.unit)}" data-price="${Number(x.default_unit_price)}" data-note="${esc(x.workmanship_note||'')}">${esc(x.item_name)}</option>`).join('');return `<div class="reno-quote-row" data-rs-quote-line data-section="${esc(section)}"><span data-rs-line-seq></span><div class="reno-quote-item-cell"><select class="field" data-rs-library aria-label="从常用项目库选择"><option value="">常用项目库…</option>${options}</select><input class="field" data-rs-name placeholder="项目名称" required></div><select class="field" data-rs-unit>${['项','投影','延米','平方','m²','m','㎡','套','个','樘'].map(x=>`<option>${x}</option>`).join('')}</select><div class="reno-quote-calc"><select hidden data-rs-mode><option>按单位</option><option>投影</option><option>延米</option><option>平方</option></select><input hidden class="field" data-rs-width type="number" min="0" step="1" placeholder="宽 mm"><input hidden class="field" data-rs-height type="number" min="0" step="1" placeholder="高 mm"><input hidden class="field" data-rs-length type="number" min="0" step=".01" placeholder="长度 m"><input class="field" data-rs-qty type="number" min="0" step=".01" value="1"></div><input class="field" data-rs-price type="number" min="0" step=".01" value="0"><strong data-rs-line-amount>¥0.00</strong><textarea class="field" data-rs-note rows="2" placeholder="工艺 / 材料 / 品牌备注"></textarea><button type="button" class="icon-btn" data-action="rs-remove-quote-line" aria-label="移除项目">×</button></div>`}
   function rsQuoteEditorPage(){if(rs.busy)return head('整装报价','正在加载报价项目库…','')+rsBanner();const id=rs.selectedCustomer,c=rsCustomer(id),n=Math.max(1,...rs.quotes.filter(q=>q.customer_id===id).map(q=>Number(q.version)+1)),today=new Date().toISOString().slice(0,10),titles=['拆除新建工程','水电暖改造工程','防水工程','木工吊顶工程','泥瓦铺贴工程','墙面油工工程','安装主材工程','其他增项'],sections=rsQuoteSections.map((s,i)=>`<section class="reno-quote-section" data-rs-section="${esc(s)}"><header><h2>${['一','二','三','四','五','六','七','八'][i]}、${titles[i]}</h2><button type="button" class="btn small" data-action="rs-add-quote-line" data-section="${esc(s)}">＋ 添加项目</button></header><div class="reno-quote-columns"><span>序号</span><span>项目名称</span><span>单位</span><span>数量</span><span>单价</span><span>合价</span><span>工艺 / 材料备注</span><span></span></div><div class="reno-quote-rows">${rsQuoteLine(s)}</div><p class="reno-quote-subtotal">分部小计：<strong data-rs-section-total>¥0.00</strong></p></section>`).join('');return head('整装报价','装修工程预算书','项目库默认值可编辑；备注支持多行填写。',`<button class="btn" data-page="quotes">返回报价列表</button>`)+`<form id="renoStaffQuote" class="reno-quote-editor"><div class="reno-quote-meta"><label>报价单号<input class="field" name="quote_no" value="YJ-${today.replaceAll('-','')}-${String(Date.now()).slice(-4)}" required></label><label>日期<input class="field" name="quote_date" type="date" value="${today}"></label><label>客户<select class="field" name="customer_id" required>${rs.customers.map(x=>`<option value="${x.id}" ${x.id===id?'selected':''}>${esc(x.name)}</option>`).join('')}</select></label><label>施工地址<input class="field" name="project_address" value="${esc([c?.community,c?.unit].filter(Boolean).join(' '))}"></label><label>设计师<input class="field" name="designer_name" placeholder="填写设计师姓名" required></label><label>设计师电话<input class="field" name="designer_phone"></label><label>有效期<select class="field" name="validity"><option>30天</option><option>60天</option><option>90天</option><option>长期有效</option></select></label><label>设计管理费<input class="field" name="design_fee" type="number" min="0" step=".01" value="0"></label><label>税费<input class="field" name="tax" type="number" min="0" step=".01" value="0"></label><label>优惠<input class="field" name="discount" type="number" min="0" step=".01" value="0"></label><input type="hidden" name="version" value="${n}"></div><p id="rsDraftStatus" class="reno-draft-status" role="status">编辑时自动保存到云端</p><div class="reno-quote-sections">${sections}</div><div class="reno-quote-grand"><div>直接费合计 <strong data-rs-quote-subtotal>¥0.00</strong></div><div>设计管理费 <strong data-rs-fee-total>¥0.00</strong></div><div>税费 <strong data-rs-tax-total>¥0.00</strong></div><div>优惠 <strong data-rs-discount-total>−¥0.00</strong></div><div class="grand-total">报价总额 <strong data-rs-total>¥0.00</strong></div></div><div class="reno-quote-submit"><button class="btn primary" type="submit">保存云端报价</button></div></form>`}
   rsQuoteForm=function(id){rs.selectedCustomer=id||rs.selectedCustomer||rs.customers[0]?.id||'';page='reno-quote-editor';module='whole';render()}
   function rsQuoteSyncMode(row){if(!row)return;const u=row.querySelector('[data-rs-unit]')?.value||'项',mode=window.__YJQuotePricingMode(u),measured=mode==='投影'||mode==='平方';row.dataset.pricingMode=mode;row.querySelector('[data-rs-mode]').value=mode;row.querySelector('[data-rs-width]').hidden=!measured;row.querySelector('[data-rs-height]').hidden=!measured;row.querySelector('[data-rs-length]').hidden=mode!=='延米';const qty=row.querySelector('[data-rs-qty]');qty.readOnly=mode!=='按单位';qty.placeholder=measured?'自动面积 m²':mode==='延米'?'自动长度 m':'数量';}
