   document.addEventListener('change',e=>{const row=e.target.closest('[data-rs-quote-line]');if(!row)return;if(e.target.matches('[data-rs-unit]'))rsQuoteSyncMode(row);if(e.target.matches('[data-rs-library]')){const o=e.target.selectedOptions[0];if(o?.value){row.querySelector('[data-rs-name]').value=o.dataset.name||'';row.querySelector('[data-rs-unit]').value=o.dataset.unit||'项';rsQuoteSyncMode(row);row.querySelector('[data-rs-price]').value=o.dataset.price||0;row.querySelector('[data-rs-note]').value=o.dataset.note||'';row.querySelector('[data-rs-note]').dispatchEvent(new Event('input',{bubbles:true}))}}rsQuoteTotals(row.closest('form'));rsQueue(row.closest('form'))},{capture:true});
