   function rsDraftItems(form){return [...form.querySelectorAll('[data-rs-quote-line]')].map((r,i)=>({line_no:i+1,space:r.dataset.section,section:r.dataset.section,item_name:r.querySelector('[data-rs-name]').value.trim(),unit:r.querySelector('[data-rs-unit]').value,quantity:Number(window.__YJQuoteQuantity(r.querySelector('[data-rs-mode]')?.value||'按单位',r.querySelector('[data-rs-qty]').value,r.querySelector('[data-rs-width]')?.value,r.querySelector('[data-rs-height]')?.value,r.querySelector('[data-rs-length]')?.value)||0),unit_price:Number(r.querySelector('[data-rs-price]').value||0),workmanship_note:r.querySelector('[data-rs-note]').value.trim(),pricing_mode:r.querySelector('[data-rs-mode]')?.value||'按单位',width_mm:Number(r.querySelector('[data-rs-width]')?.value||0)||null,height_mm:Number(r.querySelector('[data-rs-height]')?.value||0)||null,length_m:Number(r.querySelector('[data-rs-length]')?.value||0)||null})).filter(x=>x.item_name)}
