   function rsRestoreDraft(){const f=$('#renoStaffQuote'),q=rs.quotes.find(x=>x.id===rs.selectedQuote&&x.status==='草稿');if(!f||!q)return;f.dataset.quoteId=q.id;for(const k of ['quote_no','version','quote_date','design_fee','tax','discount','project_address','designer_name','designer_phone','validity'])if(f.elements[k]&&q[k]!=null)f.elements[k].value=q[k];for(const x of rs.quoteItems.filter(i=>i.quote_id===q.id)){const section=x.section||'其他增项',host=f.querySelector(`[data-rs-section="${section}"] .reno-quote-rows`);let row=[...f.querySelectorAll('[data-rs-quote-line]')].find(r=>r.dataset.section===section&&!r.querySelector('[data-rs-name]').value);if(!row){host?.insertAdjacentHTML('beforeend',rsQuoteLine(section));row=host?.lastElementChild}if(!row)continue;row.querySelector('[data-rs-name]').value=x.item_name||'';row.querySelector('[data-rs-unit]').value=x.unit||'项';row.querySelector('[data-rs-qty]').value=x.quantity||0;row.querySelector('[data-rs-price]').value=x.unit_price||0;row.querySelector('[data-rs-note]').value=x.workmanship_note||x.note||'';row.querySelector('[data-rs-mode]').value=x.pricing_mode||'按单位';row.querySelector('[data-rs-width]').value=x.width_mm||'';row.querySelector('[data-rs-height]').value=x.height_mm||'';row.querySelector('[data-rs-length]').value=x.length_m||'';rsQuoteSyncMode(row)}rsQuoteTotals(f)}
