  const ccdListPrevious=cqList;
  cqList=function(){if(!ccd.loaded)return ccdListPrevious();const cards=ccd.quotes.map(row=>{const draft=ccd.drafts.find(x=>x.id===row.id),customer=ccd.customers.find(x=>x.id===row.customer_id),payload=draft?.draft_payload||{};return `<article class="quote-saved-card"><div class="quote-saved-top"><span>${draft?'云端草稿':esc(row.status||'云端报价')}</span><small>${esc(row.id)}</small></div><h3>${esc(customer?.name||payload.customer||'客户')}</h3><p>${esc(payload.address||customer?.community||row.title||'地址待补充')}</p><div class="quote-saved-bottom"><span>${draft?`${payload.rows?.length||0} 项 · `:''}${esc(String(row.created_at||'').slice(0,10))}</span><b>${money(row.amount||0)}</b></div><div class="workshop-saved-actions">${draft?`<button class="btn small" data-action="ccd-open" data-id="${row.id}">打开并继续编辑</button>`:`<button class="btn small" data-action="ccd-open-bom" data-id="${row.id}" data-title="${esc(row.title||'定制报价')}">打开云端报价 / 交接</button>`}<button class="btn small" data-action="cq-preview-saved" data-id="${row.id}">客户报价书</button></div></article>`}).join('');return cqHead('定制报价','报价草稿、已确认报价和转厂记录均来自云端。',`<button class="btn primary" data-action="new-customer-for-quote">＋ 新建报价</button>`)+`<div class="quote-list-toolbar"><span>${ccd.quotes.length} 份云端报价 · ${ccd.drafts.length} 份可编辑草稿</span></div><div class="quote-saved-grid">${cards||'<section class="quote-list-empty"><h3>暂无云端报价</h3><p>新建报价并选择云端客户后，编辑内容会自动保存。</p></section>'}</div>`};
